//! Direct LLVM support for the canonical process representation.
//!
//! The first part of the generated-C replacement is the source-independent
//! metadata boundary: a linked runtime must discover tests and scheduled
//! processes from the design object, not from a C file generated by the
//! compiler. Execution entry points are added beside these tables as the
//! Process IR emitter gains instruction coverage.

use std::collections::HashMap;

use inkwell::builder::Builder;
use inkwell::context::Context;
use inkwell::module::{Linkage, Module};
use inkwell::values::{FunctionValue, IntValue, PointerValue};
use inkwell::AddressSpace;
use inkwell::IntPredicate;

use siox::ir::{
    Design, IndexSite, LayoutDirection, LayoutKind, ProcessActivation, ProcessAssignment,
    ProcessBinaryOp, ProcessCfg, ProcessId, ProcessInstruction, ProcessLocalId, ProcessNumber,
    ProcessSensitivity, ProcessSignalState, ProcessStorageId, ProcessTerminator, ProcessUnaryOp,
    ProcessValueId, ProcessValueKind, SignalId, SourceLayout,
};

/// Version of the native process metadata ABI emitted into every object.
///
/// This is deliberately a data version rather than the compiler package
/// version: the reusable native runtime only needs to change when one of the
/// exported table layouts or encodings changes.
const PROCESS_ABI_VERSION: u32 = 6;

/// A process returned normally and has no pending resume.
const PROCESS_COMPLETED: u8 = 0;
/// The process yielded after registering a runtime resume operation.
const PROCESS_SUSPENDED: u8 = 1;
/// The process stopped itself while leaving the simulation alive.
const PROCESS_STOPPED: u8 = 2;
/// The process requested termination of the complete simulation.
const PROCESS_FINISHED: u8 = 3;
/// This migration build encountered an instruction/terminator whose direct
/// lowering is not implemented yet. The runtime must report this, never treat
/// it as successful completion.
const PROCESS_UNSUPPORTED: u8 = u8::MAX;

fn local_state_name(process: siox::ir::ProcessId, local: ProcessLocalId) -> String {
    format!("sx.process.local.{}.{}", process.0, local.0)
}

fn storage_state_name(storage: ProcessStorageId) -> String {
    format!("sx.process.storage.{}", storage.0)
}

fn storage_old_name(storage: ProcessStorageId) -> String {
    format!("sx.process.storage.old.{}", storage.0)
}

fn layout_width(layout: &siox::ir::SourceLayout) -> Option<u32> {
    u32::try_from(layout.bit_width()?)
        .ok()
        .filter(|width| *width != 0)
}

fn local_width(
    design: &Design,
    process: siox::ir::ProcessId,
    local: ProcessLocalId,
) -> Option<u32> {
    let local = design
        .process_ir
        .processes
        .get(process.0 as usize)?
        .locals
        .get(local.0 as usize)?;
    local
        .layout
        .as_ref()
        .and_then(layout_width)
        .or_else(|| {
            local
                .ty
                .as_ref()
                .and_then(siox::types::Ty::bit_width)
                .filter(|width| *width != 0)
        })
        .or_else(|| {
            design.process_ir.values.iter().find_map(|value| {
                matches!(
                    value.kind,
                    ProcessValueKind::Local {
                        process: owner,
                        local: id,
                    } if owner == process && id == local.id
                )
                .then_some(value.bit_width)
                .flatten()
            })
        })
        .filter(|width| *width != 0 && *width <= super::emit::LLVM_MAX_INT_BITS)
}

fn storage_width(design: &Design, storage: ProcessStorageId) -> Option<u32> {
    let storage = design.process_ir.storages.get(storage.0 as usize)?;
    storage
        .layout
        .as_ref()
        .and_then(layout_width)
        .or_else(|| {
            storage
                .ty
                .as_ref()
                .and_then(siox::types::Ty::bit_width)
                .filter(|width| *width != 0)
        })
        .or_else(|| {
            design.process_ir.values.iter().find_map(|value| {
                matches!(value.kind, ProcessValueKind::Storage(id) if id == storage.id)
                    .then_some(value.bit_width)
                    .flatten()
            })
        })
        .filter(|width| *width != 0 && *width <= super::emit::LLVM_MAX_INT_BITS)
}

/// One recursively selected region within a packed process-frame value.
/// Aggregate children are laid out in source order from least-significant to
/// most-significant bits; this convention is internal to the design object.
#[derive(Clone, Copy)]
struct LayoutSlice<'a> {
    layout: &'a SourceLayout,
    offset: u32,
    width: u32,
}

fn field_slice<'a>(layout: &'a SourceLayout, field: &str) -> Option<LayoutSlice<'a>> {
    let LayoutKind::Struct { fields, .. } = &layout.kind else {
        return None;
    };
    let mut offset = 0u32;
    for candidate in fields {
        let width = layout_width(&candidate.layout)?;
        if candidate.name == field {
            return Some(LayoutSlice {
                layout: &candidate.layout,
                offset,
                width,
            });
        }
        offset = offset.checked_add(width)?;
    }
    None
}

fn array_slice(layout: &SourceLayout, index: i64) -> Option<LayoutSlice<'_>> {
    let LayoutKind::Array {
        range: Some(range),
        element,
    } = &layout.kind
    else {
        return None;
    };
    let length = u32::try_from(range.len()?).ok()?;
    let position = if range.ascending() {
        index.checked_sub(range.left)?
    } else {
        range.left.checked_sub(index)?
    };
    let position = u32::try_from(position).ok()?;
    if position >= length {
        return None;
    }
    let width = layout_width(element)?;
    Some(LayoutSlice {
        layout: element,
        offset: position.checked_mul(width)?,
        width,
    })
}

/// Follow a flattened storage-binding suffix such as `.payload[2].valid`.
fn projection_slice<'a>(layout: &'a SourceLayout, projection: &str) -> Option<LayoutSlice<'a>> {
    let mut selected = LayoutSlice {
        layout,
        offset: 0,
        width: layout_width(layout)?,
    };
    let mut rest = projection;
    while !rest.is_empty() {
        let child = if let Some(field) = rest.strip_prefix('.') {
            let boundary = field.find(['.', '[']).unwrap_or(field.len());
            let (name, tail) = field.split_at(boundary);
            rest = tail;
            field_slice(selected.layout, name)?
        } else if let Some(index) = rest.strip_prefix('[') {
            let (index, tail) = index.split_once(']')?;
            rest = tail;
            array_slice(selected.layout, index.parse().ok()?)?
        } else {
            return None;
        };
        selected.offset = selected.offset.checked_add(child.offset)?;
        selected.layout = child.layout;
        selected.width = child.width;
    }
    Some(selected)
}

fn storage_binding_slice(
    design: &Design,
    storage: ProcessStorageId,
    projection: &str,
) -> Option<(u32, u32)> {
    let metadata = design.process_ir.storages.get(storage.0 as usize)?;
    if let Some(layout) = metadata.layout.as_ref() {
        let selected = projection_slice(layout, projection)?;
        return Some((selected.offset, selected.width));
    }
    let width = storage_width(design, storage)?;
    projection.is_empty().then_some((0, width))
}

/// Every persistent value, including recursive structs/arrays, has one exact
/// packed LLVM frame. Bindings must identify a concrete region whose width
/// agrees with the flattened DUT signal.
fn storage_state_width(design: &Design, storage: ProcessStorageId) -> Option<u32> {
    let metadata = design.process_ir.storages.get(storage.0 as usize)?;
    let width = storage_width(design, storage)?;
    metadata
        .bindings
        .iter()
        .all(|binding| {
            storage_binding_slice(design, storage, &binding.projection)
                .is_some_and(|(_, selected)| design.signal_width(binding.signal) == Some(selected))
        })
        .then_some(width)
}

fn layout_default(design: &Design, layout: Option<&siox::ir::SourceLayout>) -> u64 {
    let Some(layout) = layout else { return 0 };
    let key = match &layout.kind {
        LayoutKind::Scalar {
            nominal: Some(name),
            ..
        } => Some(name.as_str()),
        LayoutKind::Scalar {
            domain: siox::ir::ScalarDomain::Enum(name),
            ..
        }
        | LayoutKind::Packed { family: name, .. } => Some(name.as_str()),
        _ => None,
    };
    key.and_then(|key| design.new_defaults.get(key).copied())
        .unwrap_or(0)
}

fn storage_default(design: &Design, storage: ProcessStorageId) -> u64 {
    layout_default(
        design,
        design
            .process_ir
            .storages
            .get(storage.0 as usize)
            .and_then(|storage| storage.layout.as_ref()),
    )
}

fn local_default(design: &Design, process: siox::ir::ProcessId, local: ProcessLocalId) -> u64 {
    layout_default(
        design,
        design
            .process_ir
            .processes
            .get(process.0 as usize)
            .and_then(|process| process.locals.get(local.0 as usize))
            .and_then(|local| local.layout.as_ref()),
    )
}

/// Declare exact-width process frames before the design ABI is emitted. The
/// design reset/commit functions call the two internal helpers whose bodies
/// are filled after all Process IR metadata is available.
pub(super) fn declare_state<'ctx>(context: &'ctx Context, module: &Module<'ctx>, design: &Design) {
    let add_state = |name: &str, width: u32| {
        let ty = context
            .custom_width_int_type(std::num::NonZeroU32::new(width).expect("nonzero state width"))
            .expect("validated process state width");
        let global = module.add_global(ty, None, name);
        global.set_initializer(&ty.const_zero());
        global.set_linkage(Linkage::Internal);
    };
    for storage in &design.process_ir.storages {
        if let Some(width) = storage_state_width(design, storage.id) {
            add_state(&storage_state_name(storage.id), width);
            add_state(&storage_old_name(storage.id), width);
        }
    }
    for process in &design.process_ir.processes {
        for local in &process.locals {
            if let Some(width) = local_width(design, process.id, local.id) {
                add_state(&local_state_name(process.id, local.id), width);
            }
        }
    }
    let storage_count = u32::try_from(design.process_ir.storages.len())
        .expect("ProcessStorageId is a u32 ABI index");
    let changed = context.i8_type().array_type(storage_count.max(1));
    let global = module.add_global(changed, None, "sx.process.storage.changed");
    global.set_initializer(&changed.const_zero());
    global.set_linkage(Linkage::Internal);

    module.add_function(
        "sx.process.reset",
        context.void_type().fn_type(&[], false),
        Some(Linkage::Internal),
    );
    module.add_function(
        "sx.process.commit.storage",
        context.bool_type().fn_type(&[], false),
        Some(Linkage::Internal),
    );
}

/// Convert an integer to another exact LLVM width without changing its
/// unsigned bit pattern.
fn fit<'ctx>(builder: &Builder<'ctx>, value: IntValue<'ctx>, width: u32) -> Option<IntValue<'ctx>> {
    let ty = value
        .get_type()
        .get_context()
        .custom_width_int_type(std::num::NonZeroU32::new(width)?)
        .ok()?;
    match value.get_type().get_bit_width().cmp(&width) {
        std::cmp::Ordering::Less => builder.build_int_z_extend(value, ty, "pv.zx").ok(),
        std::cmp::Ordering::Greater => builder.build_int_truncate(value, ty, "pv.tr").ok(),
        std::cmp::Ordering::Equal => Some(value),
    }
}

/// Signed counterpart of [`fit`].
fn fit_signed<'ctx>(
    builder: &Builder<'ctx>,
    value: IntValue<'ctx>,
    width: u32,
) -> Option<IntValue<'ctx>> {
    let ty = value
        .get_type()
        .get_context()
        .custom_width_int_type(std::num::NonZeroU32::new(width)?)
        .ok()?;
    match value.get_type().get_bit_width().cmp(&width) {
        std::cmp::Ordering::Less => builder.build_int_s_extend(value, ty, "pv.sx").ok(),
        std::cmp::Ordering::Greater => builder.build_int_truncate(value, ty, "pv.tr").ok(),
        std::cmp::Ordering::Equal => Some(value),
    }
}

/// Extract one packed aggregate region. Offsets count from the least
/// significant bit of the object-owned process frame.
fn extract_region<'ctx>(
    builder: &Builder<'ctx>,
    value: IntValue<'ctx>,
    offset: u32,
    width: u32,
) -> Option<IntValue<'ctx>> {
    let total = value.get_type().get_bit_width();
    if width == 0 || offset.checked_add(width)? > total {
        return None;
    }
    let shifted = if offset == 0 {
        value
    } else {
        builder
            .build_right_shift(
                value,
                value.get_type().const_int(u64::from(offset), false),
                false,
                "pv.aggregate.extract",
            )
            .ok()?
    };
    fit(builder, shifted, width)
}

/// Replace one packed aggregate region without disturbing neighbouring
/// fields/elements.
fn insert_region<'ctx>(
    builder: &Builder<'ctx>,
    base: IntValue<'ctx>,
    part: IntValue<'ctx>,
    offset: u32,
    width: u32,
) -> Option<IntValue<'ctx>> {
    let total = base.get_type().get_bit_width();
    if width == 0 || offset.checked_add(width)? > total {
        return None;
    }
    if offset == 0 && width == total {
        return fit(builder, part, total);
    }
    let ty = base.get_type();
    let low_mask = builder
        .build_right_shift(
            ty.const_all_ones(),
            ty.const_int(u64::from(total - width), false),
            false,
            "pv.aggregate.low_mask",
        )
        .ok()?;
    let mask = if offset == 0 {
        low_mask
    } else {
        builder
            .build_left_shift(
                low_mask,
                ty.const_int(u64::from(offset), false),
                "pv.aggregate.mask",
            )
            .ok()?
    };
    let cleared = builder
        .build_and(
            base,
            builder.build_not(mask, "pv.aggregate.keep").ok()?,
            "pv.aggregate.clear",
        )
        .ok()?;
    let part = fit(builder, part, total)?;
    let part = if offset == 0 {
        part
    } else {
        builder
            .build_left_shift(
                part,
                ty.const_int(u64::from(offset), false),
                "pv.aggregate.place",
            )
            .ok()?
    };
    builder.build_or(cleared, part, "pv.aggregate.insert").ok()
}

/// Build the recursive language default into the same packed frame used for
/// aggregate locals/storage. Leaf defaults still come from std-owned metadata.
fn layout_default_value<'ctx>(
    context: &'ctx Context,
    builder: &Builder<'ctx>,
    design: &Design,
    layout: &SourceLayout,
) -> Option<IntValue<'ctx>> {
    let width = layout_width(layout)?;
    let ty = context
        .custom_width_int_type(std::num::NonZeroU32::new(width)?)
        .ok()?;
    match &layout.kind {
        LayoutKind::Scalar { .. } | LayoutKind::Packed { .. } | LayoutKind::Opaque { .. } => {
            Some(ty.const_int(layout_default(design, Some(layout)), false))
        }
        LayoutKind::Array {
            range: Some(range),
            element,
        } => {
            let element_width = layout_width(element)?;
            let element = layout_default_value(context, builder, design, element)?;
            let mut value = ty.const_zero();
            for position in 0..u32::try_from(range.len()?).ok()? {
                value = insert_region(
                    builder,
                    value,
                    element,
                    position.checked_mul(element_width)?,
                    element_width,
                )?;
            }
            Some(value)
        }
        LayoutKind::Struct { fields, .. } => {
            let mut value = ty.const_zero();
            let mut offset = 0u32;
            for field in fields {
                let field_width = layout_width(&field.layout)?;
                value = insert_region(
                    builder,
                    value,
                    layout_default_value(context, builder, design, &field.layout)?,
                    offset,
                    field_width,
                )?;
                offset = offset.checked_add(field_width)?;
            }
            Some(value)
        }
        LayoutKind::Array { range: None, .. } => None,
    }
}

/// Read one scalar signal value through a word accessor and reconstruct its
/// exact LLVM integer. The current plane uses the stable design ABI; old/event
/// accessors remain internal to the emitted design object.
fn signal_value<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    signals: &[siox::ir::SignalId],
    state: ProcessSignalState,
    width: u32,
) -> Option<IntValue<'ctx>> {
    let [signal] = signals else {
        return None;
    };
    let signal_width = match state {
        ProcessSignalState::Current | ProcessSignalState::Old => design.signal_width(*signal)?,
        ProcessSignalState::Event => 1,
    };
    let value_type = context
        .custom_width_int_type(std::num::NonZeroU32::new(width)?)
        .ok()?;
    let read = module.get_function(match state {
        ProcessSignalState::Current => "sx_read_word",
        ProcessSignalState::Old => "sx.process.read.old",
        ProcessSignalState::Event => "sx.process.read.event",
    })?;
    let mut value = value_type.const_zero();
    // Never request or shift a word whose first bit lies outside the result.
    // A malformed hand-built IR can disagree with the signal width; treating
    // the result width as the cap keeps that mismatch from producing LLVM
    // shift poison before validation grows a stronger shape check.
    for word in 0..super::words_for(signal_width.min(width)) {
        let call = builder
            .build_call(
                read,
                &[
                    context
                        .i32_type()
                        .const_int(u64::from(signal.0), false)
                        .into(),
                    context.i32_type().const_int(u64::from(word), false).into(),
                ],
                "pv.word",
            )
            .ok()?
            .try_as_basic_value();
        let raw = match call {
            inkwell::values::ValueKind::Basic(value) => value.into_int_value(),
            _ => return None,
        };
        let placed = fit(builder, raw, width)?;
        let offset = word.checked_mul(super::ABI_WORD_BITS)?;
        let placed = if offset == 0 {
            placed
        } else {
            builder
                .build_left_shift(
                    placed,
                    value_type.const_int(u64::from(offset), false),
                    "pv.place",
                )
                .ok()?
        };
        value = builder.build_or(value, placed, "pv.join").ok()?;
    }
    Some(value)
}

fn state_value<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    name: &str,
    width: u32,
) -> Option<IntValue<'ctx>> {
    let ty = context
        .custom_width_int_type(std::num::NonZeroU32::new(width)?)
        .ok()?;
    Some(
        builder
            .build_load(ty, module.get_global(name)?.as_pointer_value(), "pv.state")
            .ok()?
            .into_int_value(),
    )
}

fn store_state<'ctx>(
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    name: &str,
    width: u32,
    value: IntValue<'ctx>,
) -> Option<()> {
    let value = fit(builder, value, width)?;
    builder
        .build_store(module.get_global(name)?.as_pointer_value(), value)
        .ok()?;
    Some(())
}

fn stage_signal<'ctx>(
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    signal: SignalId,
    value: IntValue<'ctx>,
) -> Option<()> {
    let stage = module.get_function(&format!("sx.process.stage.{}", signal.0))?;
    builder.build_call(stage, &[value.into()], "").ok()?;
    Some(())
}

/// Record the first checked-index failure in the same globals used by the
/// established hardware emitter. `active` preserves source control flow when
/// LLVM eagerly computes both operands of a value-level `select`.
fn latch_index_failure<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    valid: IntValue<'ctx>,
    offending: IntValue<'ctx>,
    active: Option<IntValue<'ctx>>,
    site: u32,
) -> Option<()> {
    let invalid = builder.build_not(valid, "pv.index.invalid").ok()?;
    let invalid = match active {
        Some(active) => builder.build_and(active, invalid, "pv.index.active").ok()?,
        None => invalid,
    };
    let i32 = context.i32_type();
    let error = module.get_global("index_error")?.as_pointer_value();
    let previous = builder
        .build_load(i32, error, "pv.index.previous")
        .ok()?
        .into_int_value();
    let empty = builder
        .build_int_compare(
            IntPredicate::EQ,
            previous,
            i32.const_zero(),
            "pv.index.empty",
        )
        .ok()?;
    let record = builder.build_and(empty, invalid, "pv.index.record").ok()?;
    let next = builder
        .build_select(
            record,
            i32.const_int(u64::from(site), false),
            previous,
            "pv.index.next",
        )
        .ok()?
        .into_int_value();
    builder.build_store(error, next).ok()?;

    let offending = fit_signed(builder, offending, 64)?;
    let value = module.get_global("index_value")?.as_pointer_value();
    let previous = builder
        .build_load(context.i64_type(), value, "pv.index.value.previous")
        .ok()?
        .into_int_value();
    let next = builder
        .build_select(record, offending, previous, "pv.index.value.next")
        .ok()?
        .into_int_value();
    builder.build_store(value, next).ok()?;
    Some(())
}

/// Latch a ranged-signal violation before the assigned value is narrowed to
/// the signal's storage width. The public query ABI is shared with the legacy
/// hardware emitter while Process IR replaces its execution path.
#[allow(clippy::too_many_arguments)]
fn latch_range_failure<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    signal: SignalId,
    value: IntValue<'ctx>,
    span: siox::diag::Span,
    range_sites: &HashMap<siox::diag::Span, u32>,
) -> Option<()> {
    let (left, right) = design.signals.get(signal.0 as usize)?.range?;
    let low = left.min(right);
    let high = left.max(right);
    let ty = value.get_type();
    let below = builder
        .build_int_compare(
            IntPredicate::SLT,
            value,
            ty.const_int(low as u64, true),
            "pv.range.below",
        )
        .ok()?;
    let above = builder
        .build_int_compare(
            IntPredicate::SGT,
            value,
            ty.const_int(high as u64, true),
            "pv.range.above",
        )
        .ok()?;
    let violation = builder.build_or(below, above, "pv.range.violation").ok()?;
    let i32 = context.i32_type();
    let error = module.get_global("range_error")?.as_pointer_value();
    let previous = builder
        .build_load(i32, error, "pv.range.previous")
        .ok()?
        .into_int_value();
    let empty = builder
        .build_int_compare(
            IntPredicate::EQ,
            previous,
            i32.const_zero(),
            "pv.range.empty",
        )
        .ok()?;
    let record = builder
        .build_and(empty, violation, "pv.range.record")
        .ok()?;
    let next = builder
        .build_select(
            record,
            i32.const_int(u64::from(signal.0) + 1, false),
            previous,
            "pv.range.next",
        )
        .ok()?
        .into_int_value();
    builder.build_store(error, next).ok()?;

    let site = module.get_global("range_site")?.as_pointer_value();
    let previous_site = builder
        .build_load(i32, site, "pv.range.site.previous")
        .ok()?
        .into_int_value();
    let site_id = range_sites.get(&span).copied().unwrap_or(0);
    let next_site = builder
        .build_select(
            record,
            i32.const_int(u64::from(site_id), false),
            previous_site,
            "pv.range.site.next",
        )
        .ok()?
        .into_int_value();
    builder.build_store(site, next_site).ok()?;

    let value = fit_signed(builder, value, 64)?;
    let stored_value = module.get_global("range_value")?.as_pointer_value();
    let previous_value = builder
        .build_load(context.i64_type(), stored_value, "pv.range.value.previous")
        .ok()?
        .into_int_value();
    let next_value = builder
        .build_select(record, value, previous_value, "pv.range.value.next")
        .ok()?
        .into_int_value();
    builder.build_store(stored_value, next_value).ok()?;
    Some(())
}

/// Compute which dependency-ordered arena nodes contain a checked access.
/// One shared table serves every process/block in the module.
fn checked_process_values(design: &Design) -> Vec<bool> {
    let mut checked = Vec::with_capacity(design.process_ir.values.len());
    let has =
        |checked: &[bool], id: ProcessValueId| checked.get(id.0 as usize).copied().unwrap_or(false);
    for value in &design.process_ir.values {
        let contains = match &value.kind {
            ProcessValueKind::CheckedIndex { .. } => true,
            ProcessValueKind::Field { base, .. }
            | ProcessValueKind::Attribute { base, .. }
            | ProcessValueKind::BitSlice { base, .. }
            | ProcessValueKind::TableLookup { index: base, .. }
            | ProcessValueKind::Unary { operand: base, .. } => has(&checked, *base),
            ProcessValueKind::Index { base, index }
            | ProcessValueKind::Binary {
                left: base,
                right: index,
                ..
            } => has(&checked, *base) || has(&checked, *index),
            ProcessValueKind::Range { left, right } => left
                .iter()
                .chain(right)
                .copied()
                .any(|value| has(&checked, value)),
            ProcessValueKind::Select {
                condition,
                then_value,
                else_value,
            } => [*condition, *then_value, *else_value]
                .into_iter()
                .any(|value| has(&checked, value)),
            ProcessValueKind::MetaCompare {
                operands, inner, ..
            } => operands
                .iter()
                .copied()
                .chain(std::iter::once(*inner))
                .any(|value| has(&checked, value)),
            ProcessValueKind::Match { scrutinee, arms } => {
                has(&checked, *scrutinee) || arms.iter().any(|arm| has(&checked, arm.value))
            }
            ProcessValueKind::Call {
                callee, arguments, ..
            } => std::iter::once(*callee)
                .chain(arguments.iter().copied())
                .any(|value| has(&checked, value)),
            ProcessValueKind::ForeignCall { arguments, .. } => {
                arguments.iter().any(|value| has(&checked, *value))
            }
            ProcessValueKind::Construct { fields, spread, .. } => fields
                .iter()
                .filter_map(|field| field.value)
                .chain(spread.iter().copied())
                .any(|value| has(&checked, value)),
            ProcessValueKind::Concat(values) | ProcessValueKind::Array(values) => {
                values.iter().any(|value| has(&checked, *value))
            }
            ProcessValueKind::Number(_)
            | ProcessValueKind::Suffixed { .. }
            | ProcessValueKind::BitString { .. }
            | ProcessValueKind::Char(_)
            | ProcessValueKind::String(_)
            | ProcessValueKind::Local { .. }
            | ProcessValueKind::Storage(_)
            | ProcessValueKind::Signal { .. }
            | ProcessValueKind::Definition(_)
            | ProcessValueKind::Intrinsic(_)
            | ProcessValueKind::Invalid => false,
        };
        checked.push(contains);
    }
    checked
}

/// Per-function value cache. Pure subgraphs use one entry regardless of the
/// enclosing branch predicate; a subgraph containing `CheckedIndex` includes
/// that predicate in its key so a shared arena node can latch independently
/// on different source control-flow paths without cloning the whole cache.
struct ProcessValueCache<'ctx, 'checks> {
    emitted: HashMap<(ProcessValueId, Option<IntValue<'ctx>>), IntValue<'ctx>>,
    checked: &'checks [bool],
}

impl<'ctx, 'checks> ProcessValueCache<'ctx, 'checks> {
    fn new(checked: &'checks [bool]) -> Self {
        Self {
            emitted: HashMap::new(),
            checked,
        }
    }

    fn contains_check(&self, value: ProcessValueId) -> bool {
        self.checked.get(value.0 as usize).copied().unwrap_or(false)
    }

    fn key(
        &self,
        value: ProcessValueId,
        active: Option<IntValue<'ctx>>,
    ) -> (ProcessValueId, Option<IntValue<'ctx>>) {
        (
            value,
            self.contains_check(value).then_some(active).flatten(),
        )
    }

    fn clear(&mut self) {
        self.emitted.clear();
    }
}

/// Emit an arena value and convert it to the operation's contextual width.
#[allow(clippy::too_many_arguments)]
fn process_value_at<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    id: ProcessValueId,
    width: u32,
    signed: bool,
    active: Option<IntValue<'ctx>>,
    index_sites: &HashMap<IndexSite, u32>,
    cache: &mut ProcessValueCache<'ctx, '_>,
) -> Option<IntValue<'ctx>> {
    let value = process_value(
        context,
        module,
        builder,
        design,
        id,
        active,
        index_sites,
        cache,
    )?;
    if signed && process_value_is_signed(design, id) {
        fit_signed(builder, value, width)
    } else {
        fit(builder, value, width)
    }
}

/// Whether a scalar arena value denotes a signed mathematical result rather
/// than merely carrying a bit pattern whose high bit happens to be set.
///
/// This distinction matters when a signed operation widens an operand. The
/// minimum representation of the positive literal `3` is `i2 3`, but it must
/// zero-extend to `i65 3`; blindly sign-extending it would turn it into `-1`.
/// Conversely, a negative-capable kernel-integer signal and the result of a
/// signed arithmetic operation must preserve their sign. This mirrors the
/// established digital emitter's contextual signed-operand rules.
fn process_value_is_signed(design: &Design, id: ProcessValueId) -> bool {
    let Some(value) = design.process_ir.values.get(id.0 as usize) else {
        return false;
    };
    match &value.kind {
        ProcessValueKind::Signal { signals, state } => {
            let [signal] = signals.as_slice() else {
                return false;
            };
            !matches!(state, ProcessSignalState::Event)
                && design.signals.get(signal.0 as usize).is_some_and(|signal| {
                    signal.integer && signal.range.map(|(left, _)| left < 0).unwrap_or(true)
                })
        }
        ProcessValueKind::Local { .. } | ProcessValueKind::Storage(_) => {
            matches!(value.ty, Some(siox::types::Ty::Integer))
        }
        ProcessValueKind::Unary { operation, .. } => matches!(
            operation,
            ProcessUnaryOp::Neg | ProcessUnaryOp::RealToInteger
        ),
        ProcessValueKind::Binary { operation, .. } => matches!(
            operation,
            ProcessBinaryOp::SignedAdd
                | ProcessBinaryOp::SignedSub
                | ProcessBinaryOp::SignedMul
                | ProcessBinaryOp::SignedDiv
                | ProcessBinaryOp::ArithmeticShr
        ),
        ProcessValueKind::Select {
            then_value,
            else_value,
            ..
        } => {
            process_value_is_signed(design, *then_value)
                || process_value_is_signed(design, *else_value)
        }
        ProcessValueKind::CheckedIndex { index, .. } => process_value_is_signed(design, *index),
        ProcessValueKind::ForeignCall { integer_result, .. } => *integer_result,
        _ => false,
    }
}

fn layout_for_type<'a>(design: &'a Design, ty: &siox::types::Ty) -> Option<&'a SourceLayout> {
    let mut candidates = design
        .process_ir
        .storages
        .iter()
        .filter(|storage| storage.ty.as_ref() == Some(ty))
        .filter_map(|storage| storage.layout.as_ref())
        .chain(
            design
                .process_ir
                .processes
                .iter()
                .flat_map(|process| &process.locals)
                .filter(|local| local.ty.as_ref() == Some(ty))
                .filter_map(|local| local.layout.as_ref()),
        );
    let first = candidates.next()?;
    candidates
        .all(|candidate| candidate == first)
        .then_some(first)
}

fn signal_layout<'a>(design: &'a Design, signals: &[SignalId]) -> Option<&'a SourceLayout> {
    let first = design.signals.get(signals.first()?.0 as usize)?;
    let mut candidates = design
        .source_layouts
        .iter()
        .filter(|(path, _)| {
            first.path == **path
                || first
                    .path
                    .strip_prefix(path.as_str())
                    .is_some_and(|suffix| suffix.starts_with('.') || suffix.starts_with('['))
        })
        .collect::<Vec<_>>();
    candidates.sort_by_key(|(path, _)| std::cmp::Reverse(path.len()));
    candidates.into_iter().find_map(|(root, layout)| {
        let suffix = first.path.strip_prefix(root)?;
        let mut prefixes = vec![""];
        let mut offset = 0usize;
        while offset < suffix.len() {
            let rest = &suffix[offset..];
            let consumed = if let Some(field) = rest.strip_prefix('.') {
                1 + field.find(['.', '[']).unwrap_or(field.len())
            } else if let Some(index) = rest.strip_prefix('[') {
                1 + index.find(']')? + 1
            } else {
                return None;
            };
            offset = offset.checked_add(consumed)?;
            prefixes.push(&suffix[..offset]);
        }
        prefixes.into_iter().rev().find_map(|projection| {
            let path = format!("{root}{projection}");
            let field = format!("{path}.");
            let element = format!("{path}[");
            let leaves = design
                .signals
                .iter()
                .enumerate()
                .filter(|(_, signal)| {
                    signal.path == path
                        || signal.path.starts_with(&field)
                        || signal.path.starts_with(&element)
                })
                .filter_map(|(index, _)| u32::try_from(index).ok())
                .filter(|index| {
                    !design.meta_of.values().any(|companion| companion == index)
                        && !design.metavalue_temps.contains(index)
                })
                .map(SignalId)
                .collect::<Vec<_>>();
            (leaves == signals)
                .then(|| projection_slice(layout, projection).map(|slice| slice.layout))
                .flatten()
        })
    })
}

/// Recursive layout carried by one arena value. This is intentionally based
/// only on finalized IR metadata: backends never consult source syntax.
fn process_value_layout(design: &Design, id: ProcessValueId) -> Option<&SourceLayout> {
    let value = design.process_ir.values.get(id.0 as usize)?;
    match &value.kind {
        ProcessValueKind::Storage(storage) => design
            .process_ir
            .storages
            .get(storage.0 as usize)?
            .layout
            .as_ref(),
        ProcessValueKind::Local { process, local } => design
            .process_ir
            .processes
            .get(process.0 as usize)?
            .locals
            .get(local.0 as usize)?
            .layout
            .as_ref(),
        ProcessValueKind::Signal { signals, .. } => signal_layout(design, signals),
        ProcessValueKind::Field { base, field } => {
            field_slice(process_value_layout(design, *base)?, field).map(|slice| slice.layout)
        }
        ProcessValueKind::Index { base, index } => {
            let index = process_constant_i64(design, *index)?;
            array_slice(process_value_layout(design, *base)?, index).map(|slice| slice.layout)
        }
        ProcessValueKind::Select {
            then_value,
            else_value,
            ..
        } => {
            let then_layout = process_value_layout(design, *then_value)?;
            (process_value_layout(design, *else_value) == Some(then_layout)).then_some(then_layout)
        }
        ProcessValueKind::Construct { ty, .. } => value
            .ty
            .as_ref()
            .or(ty.as_ref())
            .and_then(|ty| layout_for_type(design, ty)),
        ProcessValueKind::Array(_) => value.ty.as_ref().and_then(|ty| layout_for_type(design, ty)),
        _ => value.ty.as_ref().and_then(|ty| layout_for_type(design, ty)),
    }
}

fn process_constant_i64(design: &Design, id: ProcessValueId) -> Option<i64> {
    let ProcessValueKind::Number(ProcessNumber::Integer(words)) =
        &design.process_ir.values.get(id.0 as usize)?.kind
    else {
        return None;
    };
    let [word] = words.as_slice() else {
        return None;
    };
    Some(*word as i64)
}

/// Convert an arbitrary-width scalar to the one-bit condition domain.
fn as_condition<'ctx>(builder: &Builder<'ctx>, value: IntValue<'ctx>) -> Option<IntValue<'ctx>> {
    if value.get_type().get_bit_width() == 1 {
        Some(value)
    } else {
        builder
            .build_int_compare(
                IntPredicate::NE,
                value,
                value.get_type().const_zero(),
                "pv.condition",
            )
            .ok()
    }
}

/// Emit a normalized scalar binary operation with the same defined corner
/// cases as the established hardware LLVM path.
#[allow(clippy::too_many_arguments)]
fn process_binary<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    operation: &ProcessBinaryOp,
    left: ProcessValueId,
    right: ProcessValueId,
    result_width: u32,
    active: Option<IntValue<'ctx>>,
    index_sites: &HashMap<IndexSite, u32>,
    cache: &mut ProcessValueCache<'ctx, '_>,
) -> Option<IntValue<'ctx>> {
    let left_width = design.process_ir.values.get(left.0 as usize)?.bit_width?;
    let right_width = design.process_ir.values.get(right.0 as usize)?.bit_width?;

    if matches!(
        operation,
        ProcessBinaryOp::FloatAdd
            | ProcessBinaryOp::FloatSub
            | ProcessBinaryOp::FloatMul
            | ProcessBinaryOp::FloatDiv
    ) {
        let float = context.f64_type();
        let left = process_value_at(
            context,
            module,
            builder,
            design,
            left,
            64,
            false,
            active,
            index_sites,
            cache,
        )?;
        let right = process_value_at(
            context,
            module,
            builder,
            design,
            right,
            64,
            false,
            active,
            index_sites,
            cache,
        )?;
        let left = builder
            .build_bit_cast(left, float, "pv.fa")
            .ok()?
            .into_float_value();
        let right = builder
            .build_bit_cast(right, float, "pv.fb")
            .ok()?
            .into_float_value();
        let result = match operation {
            ProcessBinaryOp::FloatAdd => builder.build_float_add(left, right, "pv.fadd").ok()?,
            ProcessBinaryOp::FloatSub => builder.build_float_sub(left, right, "pv.fsub").ok()?,
            ProcessBinaryOp::FloatMul => builder.build_float_mul(left, right, "pv.fmul").ok()?,
            ProcessBinaryOp::FloatDiv => builder.build_float_div(left, right, "pv.fdiv").ok()?,
            _ => return None,
        };
        let bits = builder
            .build_bit_cast(result, context.i64_type(), "pv.fbits")
            .ok()?
            .into_int_value();
        return fit(builder, bits, result_width);
    }

    if matches!(
        operation,
        ProcessBinaryOp::FloatEq
            | ProcessBinaryOp::FloatNe
            | ProcessBinaryOp::FloatLt
            | ProcessBinaryOp::FloatLe
            | ProcessBinaryOp::FloatGt
            | ProcessBinaryOp::FloatGe
    ) {
        let float = context.f64_type();
        let left = process_value_at(
            context,
            module,
            builder,
            design,
            left,
            64,
            false,
            active,
            index_sites,
            cache,
        )?;
        let right = process_value_at(
            context,
            module,
            builder,
            design,
            right,
            64,
            false,
            active,
            index_sites,
            cache,
        )?;
        let left = builder
            .build_bit_cast(left, float, "pv.fa")
            .ok()?
            .into_float_value();
        let right = builder
            .build_bit_cast(right, float, "pv.fb")
            .ok()?
            .into_float_value();
        let predicate = match operation {
            ProcessBinaryOp::FloatEq => inkwell::FloatPredicate::OEQ,
            ProcessBinaryOp::FloatNe => inkwell::FloatPredicate::UNE,
            ProcessBinaryOp::FloatLt => inkwell::FloatPredicate::OLT,
            ProcessBinaryOp::FloatLe => inkwell::FloatPredicate::OLE,
            ProcessBinaryOp::FloatGt => inkwell::FloatPredicate::OGT,
            ProcessBinaryOp::FloatGe => inkwell::FloatPredicate::OGE,
            _ => return None,
        };
        let result = builder
            .build_float_compare(predicate, left, right, "pv.fcmp")
            .ok()?;
        return fit(builder, result, result_width);
    }

    let comparison = matches!(
        operation,
        ProcessBinaryOp::Eq
            | ProcessBinaryOp::Ne
            | ProcessBinaryOp::Lt
            | ProcessBinaryOp::Le
            | ProcessBinaryOp::Gt
            | ProcessBinaryOp::Ge
            | ProcessBinaryOp::SignedLt
            | ProcessBinaryOp::SignedLe
            | ProcessBinaryOp::SignedGt
            | ProcessBinaryOp::SignedGe
    );
    let signed = matches!(
        operation,
        ProcessBinaryOp::SignedAdd
            | ProcessBinaryOp::SignedSub
            | ProcessBinaryOp::SignedMul
            | ProcessBinaryOp::SignedDiv
            | ProcessBinaryOp::SignedLt
            | ProcessBinaryOp::SignedLe
            | ProcessBinaryOp::SignedGt
            | ProcessBinaryOp::SignedGe
            | ProcessBinaryOp::ArithmeticShr
    );
    let operand_width = if comparison {
        left_width.max(right_width)
    } else {
        result_width
    };
    let operand_width = if signed {
        operand_width.checked_add(1)?
    } else {
        operand_width
    };
    if operand_width > super::emit::LLVM_MAX_INT_BITS {
        return None;
    }

    if matches!(
        operation,
        ProcessBinaryOp::Shl | ProcessBinaryOp::Shr | ProcessBinaryOp::ArithmeticShr
    ) {
        let shift_width = operand_width.max(right_width);
        let left = process_value_at(
            context,
            module,
            builder,
            design,
            left,
            shift_width,
            matches!(operation, ProcessBinaryOp::ArithmeticShr),
            active,
            index_sites,
            cache,
        )?;
        let right = process_value_at(
            context,
            module,
            builder,
            design,
            right,
            shift_width,
            false,
            active,
            index_sites,
            cache,
        )?;
        let ty = left.get_type();
        let limit = ty.const_int(u64::from(operand_width), false);
        let out_of_range = builder
            .build_int_compare(IntPredicate::UGE, right, limit, "pv.shift.oob")
            .ok()?;
        let zero = ty.const_zero();
        let safe = builder
            .build_select(out_of_range, zero, right, "pv.shift.amount")
            .ok()?
            .into_int_value();
        let shifted = if matches!(operation, ProcessBinaryOp::Shl) {
            builder.build_left_shift(left, safe, "pv.shl").ok()?
        } else {
            builder
                .build_right_shift(
                    left,
                    safe,
                    matches!(operation, ProcessBinaryOp::ArithmeticShr),
                    "pv.shr",
                )
                .ok()?
        };
        let out_of_range_value = if matches!(operation, ProcessBinaryOp::ArithmeticShr) {
            let negative = builder
                .build_int_compare(IntPredicate::SLT, left, zero, "pv.shift.negative")
                .ok()?;
            builder
                .build_select(negative, ty.const_all_ones(), zero, "pv.shift.fill")
                .ok()?
                .into_int_value()
        } else {
            zero
        };
        let result = builder
            .build_select(out_of_range, out_of_range_value, shifted, "pv.shift.result")
            .ok()?
            .into_int_value();
        return fit(builder, result, result_width);
    }

    let left = process_value_at(
        context,
        module,
        builder,
        design,
        left,
        operand_width,
        signed,
        active,
        index_sites,
        cache,
    )?;
    let right_active = if left_width == 1
        && right_width == 1
        && cache.contains_check(right)
        && matches!(operation, ProcessBinaryOp::And | ProcessBinaryOp::Or)
    {
        let left_condition = as_condition(builder, left)?;
        let required = if matches!(operation, ProcessBinaryOp::And) {
            left_condition
        } else {
            builder
                .build_not(left_condition, "pv.or.right.active")
                .ok()?
        };
        Some(match active {
            Some(active) => builder
                .build_and(active, required, "pv.logical.right.active")
                .ok()?,
            None => required,
        })
    } else {
        active
    };
    let right = process_value_at(
        context,
        module,
        builder,
        design,
        right,
        operand_width,
        signed,
        right_active,
        index_sites,
        cache,
    )?;
    let compare = |predicate, name| {
        let value = builder
            .build_int_compare(predicate, left, right, name)
            .ok()?;
        fit(builder, value, result_width)
    };
    let result = match operation {
        ProcessBinaryOp::Add | ProcessBinaryOp::SignedAdd => {
            builder.build_int_add(left, right, "pv.add").ok()?
        }
        ProcessBinaryOp::Sub | ProcessBinaryOp::SignedSub => {
            builder.build_int_sub(left, right, "pv.sub").ok()?
        }
        ProcessBinaryOp::Mul | ProcessBinaryOp::SignedMul => {
            builder.build_int_mul(left, right, "pv.mul").ok()?
        }
        ProcessBinaryOp::Div => {
            let zero = left.get_type().const_zero();
            let one = left.get_type().const_int(1, false);
            let is_zero = builder
                .build_int_compare(IntPredicate::EQ, right, zero, "pv.div.zero")
                .ok()?;
            let safe = builder
                .build_select(is_zero, one, right, "pv.div.denominator")
                .ok()?
                .into_int_value();
            let quotient = builder.build_int_unsigned_div(left, safe, "pv.div").ok()?;
            builder
                .build_select(is_zero, zero, quotient, "pv.div.result")
                .ok()?
                .into_int_value()
        }
        ProcessBinaryOp::SignedDiv => {
            let ty = left.get_type();
            let zero = ty.const_zero();
            let one = ty.const_int(1, false);
            let negative_one = ty.const_all_ones();
            let minimum = builder
                .build_left_shift(
                    one,
                    ty.const_int(u64::from(operand_width - 1), false),
                    "pv.sdiv.minimum",
                )
                .ok()?;
            let is_zero = builder
                .build_int_compare(IntPredicate::EQ, right, zero, "pv.sdiv.zero")
                .ok()?;
            let is_minimum = builder
                .build_int_compare(IntPredicate::EQ, left, minimum, "pv.sdiv.is_minimum")
                .ok()?;
            let is_negative_one = builder
                .build_int_compare(
                    IntPredicate::EQ,
                    right,
                    negative_one,
                    "pv.sdiv.is_negative_one",
                )
                .ok()?;
            let overflow = builder
                .build_and(is_minimum, is_negative_one, "pv.sdiv.overflow")
                .ok()?;
            let unsafe_divisor = builder.build_or(is_zero, overflow, "pv.sdiv.unsafe").ok()?;
            let safe = builder
                .build_select(unsafe_divisor, one, right, "pv.sdiv.denominator")
                .ok()?
                .into_int_value();
            let quotient = builder.build_int_signed_div(left, safe, "pv.sdiv").ok()?;
            let quotient = builder
                .build_select(overflow, minimum, quotient, "pv.sdiv.overflow.result")
                .ok()?
                .into_int_value();
            builder
                .build_select(is_zero, zero, quotient, "pv.sdiv.result")
                .ok()?
                .into_int_value()
        }
        ProcessBinaryOp::And => builder.build_and(left, right, "pv.and").ok()?,
        ProcessBinaryOp::Or => builder.build_or(left, right, "pv.or").ok()?,
        ProcessBinaryOp::Xor => builder.build_xor(left, right, "pv.xor").ok()?,
        ProcessBinaryOp::Eq => return compare(IntPredicate::EQ, "pv.eq"),
        ProcessBinaryOp::Ne => return compare(IntPredicate::NE, "pv.ne"),
        ProcessBinaryOp::Lt => return compare(IntPredicate::ULT, "pv.lt"),
        ProcessBinaryOp::Le => return compare(IntPredicate::ULE, "pv.le"),
        ProcessBinaryOp::Gt => return compare(IntPredicate::UGT, "pv.gt"),
        ProcessBinaryOp::Ge => return compare(IntPredicate::UGE, "pv.ge"),
        ProcessBinaryOp::SignedLt => return compare(IntPredicate::SLT, "pv.slt"),
        ProcessBinaryOp::SignedLe => return compare(IntPredicate::SLE, "pv.sle"),
        ProcessBinaryOp::SignedGt => return compare(IntPredicate::SGT, "pv.sgt"),
        ProcessBinaryOp::SignedGe => return compare(IntPredicate::SGE, "pv.sge"),
        ProcessBinaryOp::Shl
        | ProcessBinaryOp::Shr
        | ProcessBinaryOp::ArithmeticShr
        | ProcessBinaryOp::FloatAdd
        | ProcessBinaryOp::FloatSub
        | ProcessBinaryOp::FloatMul
        | ProcessBinaryOp::FloatDiv
        | ProcessBinaryOp::FloatEq
        | ProcessBinaryOp::FloatNe
        | ProcessBinaryOp::FloatLt
        | ProcessBinaryOp::FloatLe
        | ProcessBinaryOp::FloatGt
        | ProcessBinaryOp::FloatGe
        | ProcessBinaryOp::Custom(_) => return None,
    };
    fit(builder, result, result_width)
}

fn aggregate_signal_value<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    signals: &[SignalId],
    state: ProcessSignalState,
    width: u32,
) -> Option<IntValue<'ctx>> {
    if matches!(state, ProcessSignalState::Event) {
        let mut event = context.bool_type().const_zero();
        for signal in signals {
            let leaf = signal_value(context, module, builder, design, &[*signal], state, 1)?;
            event = builder.build_or(event, leaf, "pv.aggregate.event").ok()?;
        }
        return Some(event);
    }
    let ty = context
        .custom_width_int_type(std::num::NonZeroU32::new(width)?)
        .ok()?;
    let mut packed = ty.const_zero();
    let mut offset = 0u32;
    for signal in signals {
        let leaf_width = design.signal_width(*signal)?;
        let leaf = signal_value(
            context,
            module,
            builder,
            design,
            &[*signal],
            state,
            leaf_width,
        )?;
        packed = insert_region(builder, packed, leaf, offset, leaf_width)?;
        offset = offset.checked_add(leaf_width)?;
    }
    (offset == width).then_some(packed)
}

/// Emit a value using an expected recursive layout. Aggregates have no LLVM
/// ABI of their own; they are packed only inside the design object so field
/// reads, copies, and bindings share one exact-width representation.
#[allow(clippy::too_many_arguments)]
fn process_value_in_layout<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    id: ProcessValueId,
    layout: &SourceLayout,
    active: Option<IntValue<'ctx>>,
    index_sites: &HashMap<IndexSite, u32>,
    cache: &mut ProcessValueCache<'ctx, '_>,
) -> Option<IntValue<'ctx>> {
    let cache_key = cache.key(id, active);
    if let Some(value) = cache.emitted.get(&cache_key).copied() {
        return (value.get_type().get_bit_width() == layout_width(layout)?).then_some(value);
    }
    let width = layout_width(layout)?;
    let value = design.process_ir.values.get(id.0 as usize)?;
    let emitted = match &value.kind {
        ProcessValueKind::Storage(storage) => {
            (storage_state_width(design, *storage) == Some(width)).then(|| {
                state_value(
                    context,
                    module,
                    builder,
                    &storage_state_name(*storage),
                    width,
                )
            })??
        }
        ProcessValueKind::Local { process, local } => {
            (local_width(design, *process, *local) == Some(width)).then(|| {
                state_value(
                    context,
                    module,
                    builder,
                    &local_state_name(*process, *local),
                    width,
                )
            })??
        }
        ProcessValueKind::Signal { signals, state } => {
            aggregate_signal_value(context, module, builder, design, signals, *state, width)?
        }
        ProcessValueKind::Field { base, field } => {
            let base_layout = process_value_layout(design, *base)?;
            let selected = field_slice(base_layout, field)?;
            if selected.width != width {
                return None;
            }
            let base = process_value_in_layout(
                context,
                module,
                builder,
                design,
                *base,
                base_layout,
                active,
                index_sites,
                cache,
            )?;
            extract_region(builder, base, selected.offset, selected.width)?
        }
        ProcessValueKind::Index { base, index } => {
            let base_layout = process_value_layout(design, *base)?;
            let selected = array_slice(base_layout, process_constant_i64(design, *index)?)?;
            if selected.width != width {
                return None;
            }
            let base = process_value_in_layout(
                context,
                module,
                builder,
                design,
                *base,
                base_layout,
                active,
                index_sites,
                cache,
            )?;
            extract_region(builder, base, selected.offset, selected.width)?
        }
        ProcessValueKind::Construct { fields, spread, .. } => {
            let LayoutKind::Struct {
                fields: layout_fields,
                ..
            } = &layout.kind
            else {
                return None;
            };
            let mut aggregate = match spread {
                Some(spread) => process_value_in_layout(
                    context,
                    module,
                    builder,
                    design,
                    *spread,
                    layout,
                    active,
                    index_sites,
                    cache,
                )?,
                None => layout_default_value(context, builder, design, layout)?,
            };
            let mut positional = 0usize;
            for field in fields {
                let field_index = match &field.name {
                    Some(name) => layout_fields
                        .iter()
                        .position(|candidate| candidate.name == *name)?,
                    None => {
                        let index = positional;
                        positional = positional.checked_add(1)?;
                        index
                    }
                };
                let field_layout = layout_fields.get(field_index)?;
                let field_value = process_value_in_layout(
                    context,
                    module,
                    builder,
                    design,
                    field.value?,
                    &field_layout.layout,
                    active,
                    index_sites,
                    cache,
                )?;
                let selected = field_slice(layout, &field_layout.name)?;
                aggregate = insert_region(
                    builder,
                    aggregate,
                    field_value,
                    selected.offset,
                    selected.width,
                )?;
            }
            aggregate
        }
        ProcessValueKind::Array(elements) => {
            let LayoutKind::Array {
                range: Some(range),
                element,
            } = &layout.kind
            else {
                return None;
            };
            if usize::try_from(range.len()?).ok()? != elements.len() {
                return None;
            }
            let ty = context
                .custom_width_int_type(std::num::NonZeroU32::new(width)?)
                .ok()?;
            let mut aggregate = ty.const_zero();
            let element_width = layout_width(element)?;
            for (position, element_value) in elements.iter().enumerate() {
                let value = process_value_in_layout(
                    context,
                    module,
                    builder,
                    design,
                    *element_value,
                    element,
                    active,
                    index_sites,
                    cache,
                )?;
                aggregate = insert_region(
                    builder,
                    aggregate,
                    value,
                    u32::try_from(position).ok()?.checked_mul(element_width)?,
                    element_width,
                )?;
            }
            aggregate
        }
        ProcessValueKind::Select {
            condition,
            then_value,
            else_value,
        } => {
            let condition = process_value(
                context,
                module,
                builder,
                design,
                *condition,
                active,
                index_sites,
                cache,
            )?;
            let condition = as_condition(builder, condition)?;
            let checked_arms =
                cache.contains_check(*then_value) || cache.contains_check(*else_value);
            let (then_active, else_active) = if checked_arms {
                let then_active = match active {
                    Some(outer) => builder
                        .build_and(outer, condition, "pv.aggregate.then.active")
                        .ok()?,
                    None => condition,
                };
                let not_condition = builder
                    .build_not(condition, "pv.aggregate.else.condition")
                    .ok()?;
                let else_active = match active {
                    Some(outer) => builder
                        .build_and(outer, not_condition, "pv.aggregate.else.active")
                        .ok()?,
                    None => not_condition,
                };
                (Some(then_active), Some(else_active))
            } else {
                (None, None)
            };
            let then_value = process_value_in_layout(
                context,
                module,
                builder,
                design,
                *then_value,
                layout,
                then_active,
                index_sites,
                cache,
            )?;
            let else_value = process_value_in_layout(
                context,
                module,
                builder,
                design,
                *else_value,
                layout,
                else_active,
                index_sites,
                cache,
            )?;
            builder
                .build_select(condition, then_value, else_value, "pv.aggregate.select")
                .ok()?
                .into_int_value()
        }
        _ => process_value_at(
            context,
            module,
            builder,
            design,
            id,
            width,
            false,
            active,
            index_sites,
            cache,
        )?,
    };
    cache.emitted.insert(cache_key, emitted);
    Some(emitted)
}

/// Emit the scalar subset needed by direct CFG control. Values are dependency
/// ordered, but the per-block cache also prevents a shared arena node from
/// being emitted more than once in one LLVM block. Foreign calls invalidate
/// cached signal reads because they may mutate state through the public ABI.
#[allow(clippy::too_many_arguments)]
fn process_value<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    id: ProcessValueId,
    active: Option<IntValue<'ctx>>,
    index_sites: &HashMap<IndexSite, u32>,
    cache: &mut ProcessValueCache<'ctx, '_>,
) -> Option<IntValue<'ctx>> {
    let cache_key = cache.key(id, active);
    if let Some(value) = cache.emitted.get(&cache_key).copied() {
        return Some(value);
    }
    let value = design.process_ir.values.get(id.0 as usize)?;
    let width = value.bit_width?;
    if width > super::emit::LLVM_MAX_INT_BITS {
        return None;
    }
    let ty = context
        .custom_width_int_type(std::num::NonZeroU32::new(width)?)
        .ok()?;
    let emitted = match &value.kind {
        ProcessValueKind::Number(ProcessNumber::Integer(words))
        | ProcessValueKind::BitString { words, .. } => ty.const_int_arbitrary_precision(words),
        ProcessValueKind::Number(ProcessNumber::Real(bits)) => ty.const_int(*bits, false),
        ProcessValueKind::Char(character) => ty.const_int(u64::from(u32::from(*character)), false),
        ProcessValueKind::Signal { signals, state } => {
            if signals.len() == 1 {
                signal_value(context, module, builder, design, signals, *state, width)?
            } else {
                aggregate_signal_value(context, module, builder, design, signals, *state, width)?
            }
        }
        ProcessValueKind::Local { process, local } => state_value(
            context,
            module,
            builder,
            &local_state_name(*process, *local),
            width,
        )?,
        ProcessValueKind::Storage(storage) => state_value(
            context,
            module,
            builder,
            &storage_state_name(*storage),
            width,
        )?,
        ProcessValueKind::BitSlice { base, high, low } => {
            let base = process_value(
                context,
                module,
                builder,
                design,
                *base,
                active,
                index_sites,
                cache,
            )?;
            let base_width = base.get_type().get_bit_width();
            if high < low || *high >= base_width {
                return None;
            }
            let shifted = if *low == 0 {
                base
            } else {
                builder
                    .build_right_shift(
                        base,
                        base.get_type().const_int(u64::from(*low), false),
                        false,
                        "pv.slice",
                    )
                    .ok()?
            };
            fit(builder, shifted, width)?
        }
        ProcessValueKind::CheckedIndex {
            index,
            valid,
            left,
            right,
            span,
        } => {
            let index_value = process_value(
                context,
                module,
                builder,
                design,
                *index,
                active,
                index_sites,
                cache,
            )?;
            let valid = process_value(
                context,
                module,
                builder,
                design,
                *valid,
                active,
                index_sites,
                cache,
            )?;
            let valid = as_condition(builder, valid)?;
            let site = index_sites.get(&IndexSite {
                span: *span,
                left: *left,
                right: *right,
            })?;
            let offending = if process_value_is_signed(design, *index) {
                fit_signed(builder, index_value, 64)?
            } else {
                fit(builder, index_value, 64)?
            };
            latch_index_failure(context, module, builder, valid, offending, active, *site)?;
            fit(builder, index_value, width)?
        }
        ProcessValueKind::TableLookup { table, index } => {
            let metadata = design.lookup_tables.get(table.0)?;
            let count = u64::try_from(metadata.values.len()).ok()?;
            let count_width = (64 - count.leading_zeros()).max(1);
            let index_width = design
                .process_ir
                .values
                .get(index.0 as usize)?
                .bit_width?
                .max(count_width);
            let index = process_value_at(
                context,
                module,
                builder,
                design,
                *index,
                index_width,
                false,
                active,
                index_sites,
                cache,
            )?;
            let in_range = builder
                .build_int_compare(
                    IntPredicate::ULT,
                    index,
                    index.get_type().const_int(count, false),
                    "pv.table.in_range",
                )
                .ok()?;
            let safe_index = builder
                .build_select(
                    in_range,
                    index,
                    index.get_type().const_zero(),
                    "pv.table.safe_index",
                )
                .ok()?
                .into_int_value();
            let safe_index = fit(builder, safe_index, 64)?;
            let storage_width = metadata.element_width.next_power_of_two().max(8);
            let storage = context
                .custom_width_int_type(std::num::NonZeroU32::new(storage_width)?)
                .ok()?;
            let array = storage.array_type(u32::try_from(metadata.values.len()).ok()?);
            let global = module.get_global(&format!("sx.lookup.{}", table.0))?;
            let pointer = unsafe {
                builder
                    .build_in_bounds_gep(
                        array,
                        global.as_pointer_value(),
                        &[context.i64_type().const_zero(), safe_index],
                        "pv.table.pointer",
                    )
                    .ok()?
            };
            let loaded = builder
                .build_load(storage, pointer, "pv.table.value")
                .ok()?
                .into_int_value();
            let selected = builder
                .build_select(in_range, loaded, storage.const_zero(), "pv.table.result")
                .ok()?
                .into_int_value();
            fit(builder, selected, width)?
        }
        ProcessValueKind::ForeignCall {
            name,
            arguments,
            float_arguments,
            integer_arguments,
            float_result,
            integer_result,
        } => {
            use inkwell::types::BasicMetadataTypeEnum as MetadataType;
            use inkwell::values::BasicMetadataValueEnum as MetadataValue;

            let float = context.f64_type();
            let mut parameter_types = Vec::<MetadataType>::with_capacity(arguments.len());
            let mut argument_values = Vec::<MetadataValue>::with_capacity(arguments.len());
            for (index, argument) in arguments.iter().enumerate() {
                let argument = process_value_at(
                    context,
                    module,
                    builder,
                    design,
                    *argument,
                    64,
                    integer_arguments.get(index).copied().unwrap_or(false),
                    active,
                    index_sites,
                    cache,
                )?;
                if float_arguments.get(index).copied().unwrap_or(false) {
                    parameter_types.push(float.into());
                    argument_values.push(
                        builder
                            .build_bit_cast(argument, float, "pv.foreign.float_argument")
                            .ok()?
                            .into_float_value()
                            .into(),
                    );
                } else {
                    parameter_types.push(context.i64_type().into());
                    argument_values.push(argument.into());
                }
            }
            let function = module.get_function(name).unwrap_or_else(|| {
                let signature = if *float_result {
                    float.fn_type(&parameter_types, false)
                } else {
                    context.i64_type().fn_type(&parameter_types, false)
                };
                module.add_function(name, signature, Some(Linkage::External))
            });
            let returned = match builder
                .build_call(function, &argument_values, "pv.foreign")
                .ok()?
                .try_as_basic_value()
            {
                inkwell::values::ValueKind::Basic(value) => value,
                _ => return None,
            };
            // Foreign code may call public signal accessors. Later arena reads
            // must observe that mutation rather than reuse an earlier load.
            cache.clear();
            let returned = if *float_result {
                builder
                    .build_bit_cast(
                        returned.into_float_value(),
                        context.i64_type(),
                        "pv.foreign.float_result",
                    )
                    .ok()?
                    .into_int_value()
            } else {
                returned.into_int_value()
            };
            if *integer_result {
                fit_signed(builder, returned, width)?
            } else {
                fit(builder, returned, width)?
            }
        }
        ProcessValueKind::Unary { operation, operand } => match operation {
            ProcessUnaryOp::Neg => {
                let operand = process_value_at(
                    context,
                    module,
                    builder,
                    design,
                    *operand,
                    width,
                    false,
                    active,
                    index_sites,
                    cache,
                )?;
                builder.build_int_neg(operand, "pv.neg").ok()?
            }
            ProcessUnaryOp::Not => {
                let operand = process_value(
                    context,
                    module,
                    builder,
                    design,
                    *operand,
                    active,
                    index_sites,
                    cache,
                )?;
                let inverted = builder
                    .build_int_compare(
                        IntPredicate::EQ,
                        operand,
                        operand.get_type().const_zero(),
                        "pv.not",
                    )
                    .ok()?;
                fit(builder, inverted, width)?
            }
            ProcessUnaryOp::RealToInteger => {
                let operand = process_value_at(
                    context,
                    module,
                    builder,
                    design,
                    *operand,
                    64,
                    false,
                    active,
                    index_sites,
                    cache,
                )?;
                let real = builder
                    .build_bit_cast(operand, context.f64_type(), "pv.real.bits")
                    .ok()?
                    .into_float_value();
                let integer = builder
                    .build_float_to_signed_int(real, context.i64_type(), "pv.real.integer")
                    .ok()?;
                fit_signed(builder, integer, width)?
            }
        },
        ProcessValueKind::Binary {
            operation,
            left,
            right,
        } => process_binary(
            context,
            module,
            builder,
            design,
            operation,
            *left,
            *right,
            width,
            active,
            index_sites,
            cache,
        )?,
        ProcessValueKind::Select {
            condition: selected,
            then_value,
            else_value,
        } => {
            let selected = process_value(
                context,
                module,
                builder,
                design,
                *selected,
                active,
                index_sites,
                cache,
            )?;
            let selected = as_condition(builder, selected)?;
            let checked_arms =
                cache.contains_check(*then_value) || cache.contains_check(*else_value);
            let (then_active, else_active) = if !checked_arms {
                (None, None)
            } else {
                let then_active = match active {
                    Some(outer) => Some(
                        builder
                            .build_and(outer, selected, "pv.select.then.active")
                            .ok()?,
                    ),
                    None => Some(selected),
                };
                let not_selected = builder.build_not(selected, "pv.select.not").ok()?;
                let else_active = match active {
                    Some(outer) => Some(
                        builder
                            .build_and(outer, not_selected, "pv.select.else.active")
                            .ok()?,
                    ),
                    None => Some(not_selected),
                };
                (then_active, else_active)
            };
            // LLVM `select` computes both operands in one block. Checked
            // subgraphs include their activity predicate in the cache key;
            // pure operands keep sharing one emitted value across both arms.
            let then_value = process_value_at(
                context,
                module,
                builder,
                design,
                *then_value,
                width,
                false,
                then_active,
                index_sites,
                cache,
            )?;
            let else_value = process_value_at(
                context,
                module,
                builder,
                design,
                *else_value,
                width,
                false,
                else_active,
                index_sites,
                cache,
            )?;
            builder
                .build_select(selected, then_value, else_value, "pv.select")
                .ok()?
                .into_int_value()
        }
        ProcessValueKind::Field { .. } => {
            let layout = process_value_layout(design, id)?;
            if layout_width(layout)? != width {
                return None;
            }
            process_value_in_layout(
                context,
                module,
                builder,
                design,
                id,
                layout,
                active,
                index_sites,
                cache,
            )?
        }
        ProcessValueKind::Index { base, index } => {
            let base_layout = process_value_layout(design, *base)?;
            match &base_layout.kind {
                LayoutKind::Array { .. } => {
                    let layout = process_value_layout(design, id)?;
                    if layout_width(layout)? != width {
                        return None;
                    }
                    process_value_in_layout(
                        context,
                        module,
                        builder,
                        design,
                        id,
                        layout,
                        active,
                        index_sites,
                        cache,
                    )?
                }
                LayoutKind::Packed {
                    range: Some(range), ..
                } if width == 1 => {
                    let index = process_constant_i64(design, *index)?;
                    let low = range.left.min(range.right);
                    let offset = u32::try_from(index.checked_sub(low)?).ok()?;
                    let base_width = layout_width(base_layout)?;
                    if offset >= base_width {
                        return None;
                    }
                    let base = process_value_at(
                        context,
                        module,
                        builder,
                        design,
                        *base,
                        base_width,
                        false,
                        active,
                        index_sites,
                        cache,
                    )?;
                    extract_region(builder, base, offset, 1)?
                }
                _ => return None,
            }
        }
        ProcessValueKind::Concat(parts) => {
            let mut joined = ty.const_zero();
            let mut offset = width;
            for part in parts {
                let part_width = design.process_ir.values.get(part.0 as usize)?.bit_width?;
                offset = offset.checked_sub(part_width)?;
                let part = process_value_at(
                    context,
                    module,
                    builder,
                    design,
                    *part,
                    width,
                    false,
                    active,
                    index_sites,
                    cache,
                )?;
                let part = if offset == 0 {
                    part
                } else {
                    builder
                        .build_left_shift(
                            part,
                            ty.const_int(u64::from(offset), false),
                            "pv.concat.place",
                        )
                        .ok()?
                };
                joined = builder.build_or(joined, part, "pv.concat").ok()?;
            }
            if offset != 0 {
                return None;
            }
            joined
        }
        _ => return None,
    };
    cache.emitted.insert(cache_key, emitted);
    Some(emitted)
}

/// Emit one externally visible, immutable `u32` value.
fn u32_global<'ctx>(context: &'ctx Context, module: &Module<'ctx>, name: &str, value: u32) {
    let ty = context.i32_type();
    let global = module.add_global(ty, None, name);
    global.set_initializer(&ty.const_int(u64::from(value), false));
    global.set_constant(true);
}

/// Emit an externally visible `u32[]`, retaining one zero sentinel for an
/// empty logical table because C cannot portably declare a zero-sized array.
fn u32_table<'ctx>(context: &'ctx Context, module: &Module<'ctx>, name: &str, values: &[u32]) {
    let ty = context.i32_type();
    let values = values
        .iter()
        .copied()
        .map(|value| ty.const_int(u64::from(value), false))
        .collect::<Vec<_>>();
    let fallback = [ty.const_zero()];
    let initializer = ty.const_array(if values.is_empty() {
        &fallback
    } else {
        &values
    });
    let global = module.add_global(initializer.get_type(), None, name);
    global.set_initializer(&initializer);
    global.set_constant(true);
}

/// Emit an externally visible `u8[]`, with the same empty-table convention as
/// [`u32_table`].
fn u8_table<'ctx>(context: &'ctx Context, module: &Module<'ctx>, name: &str, values: &[u8]) {
    let ty = context.i8_type();
    let values = values
        .iter()
        .copied()
        .map(|value| ty.const_int(u64::from(value), false))
        .collect::<Vec<_>>();
    let fallback = [ty.const_zero()];
    let initializer = ty.const_array(if values.is_empty() {
        &fallback
    } else {
        &values
    });
    let global = module.add_global(initializer.get_type(), None, name);
    global.set_initializer(&initializer);
    global.set_constant(true);
}

/// Emit a private NUL-terminated string and return its constant address.
fn private_string<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    name: &str,
    value: &str,
) -> PointerValue<'ctx> {
    let initializer = context.const_string(value.as_bytes(), true);
    let global = module.add_global(initializer.get_type(), None, name);
    global.set_initializer(&initializer);
    global.set_constant(true);
    global.set_linkage(Linkage::Private);
    global.as_pointer_value()
}

/// Emit externally visible `const char *const[]` test names. The logical
/// length is always `sx_test_count`; an empty design carries one null sentinel.
fn test_name_table<'ctx>(context: &'ctx Context, module: &Module<'ctx>, design: &Design) {
    let pointer = context.ptr_type(AddressSpace::default());
    let values = design
        .process_ir
        .tests
        .iter()
        .enumerate()
        .map(|(index, test)| {
            private_string(
                context,
                module,
                &format!("sx.test.name.{index}"),
                &test.qualified_name,
            )
        })
        .collect::<Vec<_>>();
    let fallback = [pointer.const_null()];
    let initializer = pointer.const_array(if values.is_empty() {
        &fallback
    } else {
        &values
    });
    let global = module.add_global(initializer.get_type(), None, "sx_test_names");
    global.set_initializer(&initializer);
    global.set_constant(true);
}

/// Compute which arena nodes the direct scalar emitter can lower. Values are
/// dependency ordered, so this stays iterative and cannot overflow the Rust
/// stack on a large generated expression graph.
fn supported_process_values(design: &Design) -> Vec<bool> {
    let mut supported = Vec::with_capacity(design.process_ir.values.len());
    let has = |supported: &[bool], id: ProcessValueId| {
        supported.get(id.0 as usize).copied().unwrap_or(false)
    };
    for (index, value) in design.process_ir.values.iter().enumerate() {
        let id = ProcessValueId(index as u32);
        let scalar_width = value
            .bit_width
            .is_some_and(|width| width != 0 && width <= super::emit::LLVM_MAX_INT_BITS);
        let aggregate_width = process_value_layout(design, id)
            .and_then(layout_width)
            .is_some_and(|width| width <= super::emit::LLVM_MAX_INT_BITS);
        let shape = match &value.kind {
            ProcessValueKind::Number(_)
            | ProcessValueKind::BitString { .. }
            | ProcessValueKind::Char(_) => true,
            ProcessValueKind::Signal { signals, state } => {
                !signals.is_empty()
                    && signals
                        .iter()
                        .all(|signal| design.signals.get(signal.0 as usize).is_some())
                    && if matches!(state, ProcessSignalState::Event) {
                        value.bit_width == Some(1)
                    } else {
                        signals.iter().try_fold(0u32, |width, signal| {
                            width.checked_add(design.signal_width(*signal)?)
                        }) == value.bit_width
                    }
            }
            ProcessValueKind::BitSlice { base, high, low } => {
                has(&supported, *base)
                    && low <= high
                    && design
                        .process_ir
                        .values
                        .get(base.0 as usize)
                        .and_then(|value| value.bit_width)
                        .is_some_and(|width| *high < width)
            }
            ProcessValueKind::CheckedIndex { index, valid, .. } => {
                has(&supported, *index)
                    && has(&supported, *valid)
                    && value.bit_width
                        == design
                            .process_ir
                            .values
                            .get(index.0 as usize)
                            .and_then(|index| index.bit_width)
            }
            ProcessValueKind::TableLookup { table, index } => {
                has(&supported, *index)
                    && design.lookup_tables.get(table.0).is_some_and(|table| {
                        !table.values.is_empty()
                            && table.values.len() <= u32::MAX as usize
                            && (1..=64).contains(&table.element_width)
                    })
            }
            ProcessValueKind::ForeignCall {
                arguments,
                float_arguments,
                integer_arguments,
                ..
            } => {
                arguments.len() == float_arguments.len()
                    && arguments.len() == integer_arguments.len()
                    && arguments.iter().all(|argument| has(&supported, *argument))
            }
            ProcessValueKind::Local { process, local } => {
                local_width(design, *process, *local) == value.bit_width
            }
            ProcessValueKind::Storage(storage) => {
                storage_state_width(design, *storage) == value.bit_width
                    && design
                        .process_ir
                        .storages
                        .get(storage.0 as usize)
                        .is_some_and(|storage| {
                            storage
                                .initializer
                                .is_none_or(|initializer| has(&supported, initializer))
                        })
            }
            ProcessValueKind::Unary { operand, .. } => has(&supported, *operand),
            ProcessValueKind::Binary {
                operation,
                left,
                right,
            } => {
                !matches!(operation, ProcessBinaryOp::Custom(_))
                    && has(&supported, *left)
                    && has(&supported, *right)
            }
            ProcessValueKind::Select {
                condition,
                then_value,
                else_value,
            } => {
                has(&supported, *condition)
                    && has(&supported, *then_value)
                    && has(&supported, *else_value)
            }
            ProcessValueKind::Field { base, .. } => {
                has(&supported, *base) && process_value_layout(design, id).is_some()
            }
            ProcessValueKind::Index { base, index } => {
                if !has(&supported, *base) || !has(&supported, *index) {
                    false
                } else {
                    let selected = process_constant_i64(design, *index);
                    match process_value_layout(design, *base) {
                        Some(
                            layout @ SourceLayout {
                                kind: LayoutKind::Array { .. },
                                ..
                            },
                        ) => selected.is_some_and(|index| array_slice(layout, index).is_some()),
                        Some(SourceLayout {
                            kind:
                                LayoutKind::Packed {
                                    range: Some(range), ..
                                },
                            ..
                        }) => {
                            selected.is_some_and(|index| {
                                (range.left.min(range.right)..=range.left.max(range.right))
                                    .contains(&index)
                            }) && value.bit_width == Some(1)
                        }
                        _ => false,
                    }
                }
            }
            ProcessValueKind::Construct { fields, spread, .. } => {
                process_value_layout(design, id).is_some()
                    && fields
                        .iter()
                        .all(|field| field.value.is_some_and(|value| has(&supported, value)))
                    && spread.is_none_or(|spread| has(&supported, spread))
            }
            ProcessValueKind::Array(elements) => {
                process_value_layout(design, id).is_some()
                    && elements.iter().all(|element| has(&supported, *element))
            }
            ProcessValueKind::Concat(parts) => {
                parts.iter().all(|part| has(&supported, *part))
                    && parts.iter().try_fold(0u32, |width, part| {
                        width.checked_add(design.process_ir.values.get(part.0 as usize)?.bit_width?)
                    }) == value.bit_width
            }
            ProcessValueKind::Suffixed { .. }
            | ProcessValueKind::String(_)
            | ProcessValueKind::Definition(_)
            | ProcessValueKind::Intrinsic(_)
            | ProcessValueKind::Attribute { .. }
            | ProcessValueKind::Range { .. }
            | ProcessValueKind::MetaCompare { .. }
            | ProcessValueKind::Match { .. }
            | ProcessValueKind::Call { .. }
            | ProcessValueKind::Invalid => false,
        };
        supported.push((scalar_width || aggregate_width) && shape);
    }
    supported
}

/// Resolve a whole current-signal place. Keeping this fast path preserves the
/// source expression's wider mathematical value for range checking before it
/// is narrowed to the signal's representation.
fn staged_signal_target(design: &Design, target: ProcessValueId) -> Option<SignalId> {
    let signals = staged_signal_group(design, target)?;
    let [signal] = signals else {
        return None;
    };
    Some(*signal)
}

fn staged_signal_group(design: &Design, target: ProcessValueId) -> Option<&[SignalId]> {
    let value = design.process_ir.values.get(target.0 as usize)?;
    let ProcessValueKind::Signal { signals, state } = &value.kind else {
        return None;
    };
    let width = signals.iter().try_fold(0u32, |width, signal| {
        width.checked_add(design.signal_width(*signal)?)
    })?;
    (matches!(state, ProcessSignalState::Current)
        && !signals.is_empty()
        && value.bit_width == Some(width))
    .then_some(signals)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum StaticPlaceRoot {
    Local(ProcessId, ProcessLocalId),
    Storage(ProcessStorageId),
    Signal(SignalId),
}

#[derive(Clone, Copy, Debug)]
struct StaticPlace {
    root: StaticPlaceRoot,
    root_width: u32,
    offset: u32,
    width: u32,
}

#[derive(Clone, Copy)]
struct ScheduleSite {
    id: u32,
    process: ProcessId,
    block: siox::ir::ProcessBlockId,
    instruction: usize,
    target: ProcessValueId,
    width: u32,
    span: siox::diag::Span,
}

/// A delayed write may target object-owned storage or a signal, but never a
/// lexical local: the local could have ended before the event expires. Ranged
/// endpoints stay fail-closed until the event ABI retains the wider
/// mathematical source value used by their diagnostic.
fn delayed_place(design: &Design, target: ProcessValueId) -> Option<StaticPlace> {
    let place = static_place(design, target)?;
    match place.root {
        StaticPlaceRoot::Local(_, _) => None,
        StaticPlaceRoot::Signal(signal) => design
            .signals
            .get(signal.0 as usize)?
            .range
            .is_none()
            .then_some(place),
        StaticPlaceRoot::Storage(storage) => design
            .process_ir
            .storages
            .get(storage.0 as usize)?
            .bindings
            .iter()
            .all(|binding| {
                design
                    .signals
                    .get(binding.signal.0 as usize)
                    .is_some_and(|signal| signal.range.is_none())
            })
            .then_some(place),
    }
}

fn schedule_sites(design: &Design) -> Vec<ScheduleSite> {
    let mut sites = Vec::new();
    for process in &design.process_ir.processes {
        for block in &process.blocks {
            for (instruction, node) in block.instructions.iter().enumerate() {
                let ProcessInstruction::Schedule { target, span, .. } = node else {
                    continue;
                };
                let Some(place) = delayed_place(design, *target) else {
                    continue;
                };
                sites.push(ScheduleSite {
                    id: sites.len() as u32,
                    process: process.id,
                    block: block.id,
                    instruction,
                    target: *target,
                    width: place.width,
                    span: *span,
                });
            }
        }
    }
    sites
}

fn static_place(design: &Design, id: ProcessValueId) -> Option<StaticPlace> {
    let value = design.process_ir.values.get(id.0 as usize)?;
    match &value.kind {
        ProcessValueKind::Local { process, local } => {
            let width = local_width(design, *process, *local)?;
            (value.bit_width == Some(width)).then_some(StaticPlace {
                root: StaticPlaceRoot::Local(*process, *local),
                root_width: width,
                offset: 0,
                width,
            })
        }
        ProcessValueKind::Storage(storage) => {
            let width = storage_state_width(design, *storage)?;
            (value.bit_width == Some(width)).then_some(StaticPlace {
                root: StaticPlaceRoot::Storage(*storage),
                root_width: width,
                offset: 0,
                width,
            })
        }
        ProcessValueKind::Signal { signals, state } => {
            let [signal] = signals.as_slice() else {
                return None;
            };
            if !matches!(state, ProcessSignalState::Current) {
                return None;
            }
            let width = design.signal_width(*signal)?;
            (value.bit_width == Some(width)).then_some(StaticPlace {
                root: StaticPlaceRoot::Signal(*signal),
                root_width: width,
                offset: 0,
                width,
            })
        }
        ProcessValueKind::Field { base, field } => {
            let mut place = static_place(design, *base)?;
            let selected = field_slice(process_value_layout(design, *base)?, field)?;
            place.offset = place.offset.checked_add(selected.offset)?;
            place.width = selected.width;
            (value.bit_width == Some(selected.width)).then_some(place)
        }
        ProcessValueKind::Index { base, index } => {
            let mut place = static_place(design, *base)?;
            let base_layout = process_value_layout(design, *base)?;
            let index = process_constant_i64(design, *index)?;
            let (offset, width) = match &base_layout.kind {
                LayoutKind::Array { .. } => {
                    let selected = array_slice(base_layout, index)?;
                    (selected.offset, selected.width)
                }
                LayoutKind::Packed {
                    range: Some(range), ..
                } => {
                    let low = range.left.min(range.right);
                    let offset = u32::try_from(index.checked_sub(low)?).ok()?;
                    (offset, 1)
                }
                _ => return None,
            };
            place.offset = place.offset.checked_add(offset)?;
            place.width = width;
            (place.offset.checked_add(width)? <= place.root_width && value.bit_width == Some(width))
                .then_some(place)
        }
        _ => None,
    }
}

fn place_has_semantics(place: StaticPlace, owner: ProcessId, semantics: ProcessAssignment) -> bool {
    matches!(
        (place.root, semantics),
        (
            StaticPlaceRoot::Local(process, _),
            ProcessAssignment::ImmediateLocal
        ) if process == owner
    ) || matches!(
        (place.root, semantics),
        (
            StaticPlaceRoot::Storage(_),
            ProcessAssignment::ImmediateStorage
        ) | (StaticPlaceRoot::Signal(_), ProcessAssignment::StagedSignal)
    )
}

fn place_class(place: StaticPlace, owner: ProcessId) -> Option<u8> {
    match place.root {
        StaticPlaceRoot::Local(process, _) if process == owner => Some(0),
        StaticPlaceRoot::Storage(_) => Some(1),
        StaticPlaceRoot::Signal(_) => Some(2),
        StaticPlaceRoot::Local(_, _) => None,
    }
}

fn per_place_targets(design: &Design, target: ProcessValueId) -> Option<Vec<StaticPlace>> {
    let ProcessValueKind::Concat(parts) = &design.process_ir.values.get(target.0 as usize)?.kind
    else {
        return None;
    };
    let places = parts
        .iter()
        .map(|part| static_place(design, *part))
        .collect::<Option<Vec<_>>>()?;
    let mut roots = std::collections::HashSet::new();
    (!places.is_empty() && places.iter().all(|place| roots.insert(place.root))).then_some(places)
}

fn supported_per_place_assignment(
    design: &Design,
    owner: ProcessId,
    target: ProcessValueId,
    value: ProcessValueId,
) -> bool {
    let Some(places) = per_place_targets(design, target) else {
        return false;
    };
    let mut classes = std::collections::HashSet::new();
    let Some(width) = places.iter().try_fold(0u32, |width, place| {
        classes.insert(place_class(*place, owner)?);
        width.checked_add(place.width)
    }) else {
        return false;
    };
    classes.len() > 1
        && design
            .process_ir
            .values
            .get(value.0 as usize)
            .and_then(|value| value.bit_width)
            == Some(width)
}

#[allow(clippy::too_many_arguments)]
fn assignment_value<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    target: ProcessValueId,
    value: ProcessValueId,
    width: u32,
    index_sites: &HashMap<IndexSite, u32>,
    cache: &mut ProcessValueCache<'ctx, '_>,
) -> Option<IntValue<'ctx>> {
    if let Some(layout) =
        process_value_layout(design, target).filter(|layout| layout_width(layout) == Some(width))
    {
        process_value_in_layout(
            context,
            module,
            builder,
            design,
            value,
            layout,
            None,
            index_sites,
            cache,
        )
    } else {
        process_value_at(
            context,
            module,
            builder,
            design,
            value,
            width,
            false,
            None,
            index_sites,
            cache,
        )
    }
}

#[allow(clippy::too_many_arguments)]
fn stage_storage_value<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    storage: ProcessStorageId,
    value: IntValue<'ctx>,
    span: siox::diag::Span,
    range_sites: &HashMap<siox::diag::Span, u32>,
) -> Option<()> {
    let metadata = design.process_ir.storages.get(storage.0 as usize)?;
    for binding in &metadata.bindings {
        if !matches!(
            binding.direction,
            LayoutDirection::In | LayoutDirection::InOut
        ) {
            continue;
        }
        let signal = binding.signal;
        let (offset, binding_width) = storage_binding_slice(design, storage, &binding.projection)?;
        let signal_width = design.signal_width(signal)?;
        let part = extract_region(builder, value, offset, binding_width)?;
        let ranged = design.signals.get(signal.0 as usize)?.range.is_some();
        let staged = if ranged {
            let checked_width = binding_width.max(signal_width).max(64);
            let checked = if design.signals.get(signal.0 as usize)?.integer {
                fit_signed(builder, part, checked_width)?
            } else {
                fit(builder, part, checked_width)?
            };
            latch_range_failure(
                context,
                module,
                builder,
                design,
                signal,
                checked,
                span,
                range_sites,
            )?;
            fit(builder, checked, signal_width)?
        } else {
            fit(builder, part, signal_width)?
        };
        stage_signal(module, builder, signal, staged)?;
    }
    Some(())
}

#[allow(clippy::too_many_arguments)]
fn stage_signal_group<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    signals: &[SignalId],
    value: IntValue<'ctx>,
    span: siox::diag::Span,
    range_sites: &HashMap<siox::diag::Span, u32>,
) -> Option<()> {
    let mut offset = 0u32;
    for signal in signals {
        let width = design.signal_width(*signal)?;
        let part = extract_region(builder, value, offset, width)?;
        if design.signals.get(signal.0 as usize)?.range.is_some() {
            let checked_width = width.max(64);
            let checked = if design.signals.get(signal.0 as usize)?.integer {
                fit_signed(builder, part, checked_width)?
            } else {
                fit(builder, part, checked_width)?
            };
            latch_range_failure(
                context,
                module,
                builder,
                design,
                *signal,
                checked,
                span,
                range_sites,
            )?;
        }
        stage_signal(module, builder, *signal, part)?;
        offset = offset.checked_add(width)?;
    }
    (offset == value.get_type().get_bit_width()).then_some(())
}

#[allow(clippy::too_many_arguments)]
fn write_static_place<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    place: StaticPlace,
    value: IntValue<'ctx>,
    span: siox::diag::Span,
    range_sites: &HashMap<siox::diag::Span, u32>,
) -> Option<()> {
    let value = fit(builder, value, place.width)?;
    match place.root {
        StaticPlaceRoot::Local(process, local) => {
            let name = local_state_name(process, local);
            let value = if place.offset == 0 && place.width == place.root_width {
                value
            } else {
                insert_region(
                    builder,
                    state_value(context, module, builder, &name, place.root_width)?,
                    value,
                    place.offset,
                    place.width,
                )?
            };
            store_state(module, builder, &name, place.root_width, value)
        }
        StaticPlaceRoot::Storage(storage) => {
            let name = storage_state_name(storage);
            let value = if place.offset == 0 && place.width == place.root_width {
                value
            } else {
                insert_region(
                    builder,
                    state_value(context, module, builder, &name, place.root_width)?,
                    value,
                    place.offset,
                    place.width,
                )?
            };
            store_state(module, builder, &name, place.root_width, value)?;
            stage_storage_value(
                context,
                module,
                builder,
                design,
                storage,
                value,
                span,
                range_sites,
            )
        }
        StaticPlaceRoot::Signal(signal) => {
            let value = if place.offset == 0 && place.width == place.root_width {
                value
            } else {
                insert_region(
                    builder,
                    signal_value(
                        context,
                        module,
                        builder,
                        design,
                        &[signal],
                        ProcessSignalState::Current,
                        place.root_width,
                    )?,
                    value,
                    place.offset,
                    place.width,
                )?
            };
            if design.signals.get(signal.0 as usize)?.range.is_some() {
                let checked_width = place.root_width.max(64);
                let checked = if design.signals.get(signal.0 as usize)?.integer {
                    fit_signed(builder, value, checked_width)?
                } else {
                    fit(builder, value, checked_width)?
                };
                latch_range_failure(
                    context,
                    module,
                    builder,
                    design,
                    signal,
                    checked,
                    span,
                    range_sites,
                )?;
            }
            stage_signal(module, builder, signal, value)
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn emit_schedule_call<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    site: u32,
    target: ProcessValueId,
    value: ProcessValueId,
    delay: ProcessValueId,
    index_sites: &HashMap<IndexSite, u32>,
    cache: &mut ProcessValueCache<'ctx, '_>,
) -> Option<()> {
    let place = delayed_place(design, target)?;
    let captured = assignment_value(
        context,
        module,
        builder,
        design,
        target,
        value,
        place.width,
        index_sites,
        cache,
    )?;
    let delay = process_value_at(
        context,
        module,
        builder,
        design,
        delay,
        64,
        false,
        None,
        index_sites,
        cache,
    )?;

    let i32 = context.i32_type();
    let i64 = context.i64_type();
    let pointer = context.ptr_type(AddressSpace::default());
    let word_count = super::words_for(place.width);
    let array = i64.array_type(word_count);
    let words = builder.build_alloca(array, "process.schedule.words").ok()?;
    for word in 0..word_count {
        let offset = word.checked_mul(super::ABI_WORD_BITS)?;
        let part = if offset == 0 {
            captured
        } else {
            builder
                .build_right_shift(
                    captured,
                    captured.get_type().const_int(u64::from(offset), false),
                    false,
                    "process.schedule.word.shift",
                )
                .ok()?
        };
        let part = fit(builder, part, 64)?;
        let destination = unsafe {
            builder
                .build_in_bounds_gep(
                    array,
                    words,
                    &[i32.const_zero(), i32.const_int(u64::from(word), false)],
                    "process.schedule.word.pointer",
                )
                .ok()?
        };
        builder.build_store(destination, part).ok()?;
    }

    let function = module
        .get_function("sx_runtime_schedule")
        .unwrap_or_else(|| {
            module.add_function(
                "sx_runtime_schedule",
                context
                    .void_type()
                    .fn_type(&[i32.into(), i64.into(), pointer.into(), i32.into()], false),
                Some(Linkage::External),
            )
        });
    builder
        .build_call(
            function,
            &[
                i32.const_int(u64::from(site), false).into(),
                delay.into(),
                words.into(),
                i32.const_int(u64::from(word_count), false).into(),
            ],
            "",
        )
        .ok()?;
    Some(())
}

fn storage_changed_ptr<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    count: u32,
    storage: u32,
) -> PointerValue<'ctx> {
    storage_changed_ptr_at(
        context,
        module,
        builder,
        count,
        context.i32_type().const_int(u64::from(storage), false),
    )
}

fn storage_changed_ptr_at<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    count: u32,
    storage: IntValue<'ctx>,
) -> PointerValue<'ctx> {
    let byte = context.i8_type();
    let table = byte.array_type(count.max(1));
    let global = module
        .get_global("sx.process.storage.changed")
        .expect("process storage change table");
    unsafe {
        builder
            .build_in_bounds_gep(
                table,
                global.as_pointer_value(),
                &[context.i32_type().const_zero(), storage],
                "process.storage.changed.pointer",
            )
            .expect("valid storage change pointer")
    }
}

/// Fill the process-frame reset/commit helpers declared before the design ABI
/// and expose storage-change queries beside signal-change queries.
fn emit_state_helpers<'ctx>(context: &'ctx Context, module: &Module<'ctx>, design: &Design) {
    let builder = context.create_builder();
    let byte = context.i8_type();
    let storage_count = u32::try_from(design.process_ir.storages.len())
        .expect("ProcessStorageId is a u32 ABI index");
    let supported_values = supported_process_values(design);
    let checked_values = checked_process_values(design);
    let index_sites = design
        .index_sites()
        .into_iter()
        .enumerate()
        .map(|(index, site)| (site, index as u32 + 1))
        .collect::<HashMap<_, _>>();

    let reset = module
        .get_function("sx.process.reset")
        .expect("process reset declaration");
    builder.position_at_end(context.append_basic_block(reset, "entry"));
    for process in &design.process_ir.processes {
        for local in &process.locals {
            let Some(width) = local_width(design, process.id, local.id) else {
                continue;
            };
            let ty = context
                .custom_width_int_type(std::num::NonZeroU32::new(width).unwrap())
                .expect("validated local width");
            store_state(
                module,
                &builder,
                &local_state_name(process.id, local.id),
                width,
                ty.const_zero(),
            )
            .expect("declared process local state");
        }
    }
    let mut cache = ProcessValueCache::new(&checked_values);
    for storage in &design.process_ir.storages {
        builder
            .build_store(
                storage_changed_ptr(context, module, &builder, storage_count, storage.id.0),
                byte.const_zero(),
            )
            .unwrap();
        let Some(width) = storage_state_width(design, storage.id) else {
            continue;
        };
        let ty = context
            .custom_width_int_type(std::num::NonZeroU32::new(width).unwrap())
            .expect("validated storage width");
        let initialized = storage
            .initializer
            .filter(|initializer| {
                supported_values
                    .get(initializer.0 as usize)
                    .copied()
                    .unwrap_or(false)
            })
            .and_then(|initializer| {
                if let Some(layout) = storage.layout.as_ref() {
                    process_value_in_layout(
                        context,
                        module,
                        &builder,
                        design,
                        initializer,
                        layout,
                        None,
                        &index_sites,
                        &mut cache,
                    )
                } else {
                    process_value_at(
                        context,
                        module,
                        &builder,
                        design,
                        initializer,
                        width,
                        false,
                        None,
                        &index_sites,
                        &mut cache,
                    )
                }
            });
        let mut value = if let Some(initialized) = initialized {
            initialized
        } else if let Some(layout) = storage.layout.as_ref() {
            layout_default_value(context, &builder, design, layout)
                .unwrap_or_else(|| ty.const_zero())
        } else {
            ty.const_int(storage_default(design, storage.id), false)
        };
        // Pure output fields are observations, not reset-time drivers. Read
        // their already-reset DUT leaves into the packed storage object.
        for binding in &storage.bindings {
            if !matches!(binding.direction, LayoutDirection::Out) {
                continue;
            }
            let (offset, binding_width) =
                storage_binding_slice(design, storage.id, &binding.projection)
                    .expect("validated storage binding");
            let observed = signal_value(
                context,
                module,
                &builder,
                design,
                &[binding.signal],
                ProcessSignalState::Current,
                binding_width,
            )
            .expect("validated observed storage binding");
            value = insert_region(&builder, value, observed, offset, binding_width)
                .expect("validated observed storage region");
        }
        store_state(
            module,
            &builder,
            &storage_state_name(storage.id),
            width,
            value,
        )
        .expect("declared process storage state");
        store_state(
            module,
            &builder,
            &storage_old_name(storage.id),
            width,
            value,
        )
        .expect("declared process storage snapshot");
        for binding in &storage.bindings {
            if !matches!(
                binding.direction,
                LayoutDirection::In | LayoutDirection::InOut
            ) {
                continue;
            }
            let (offset, binding_width) =
                storage_binding_slice(design, storage.id, &binding.projection)
                    .expect("validated storage binding");
            let staged = extract_region(&builder, value, offset, binding_width)
                .expect("validated writable storage region");
            stage_signal(module, &builder, binding.signal, staged)
                .expect("validated storage binding signal");
        }
        cache.clear();
    }
    builder.build_return(None).unwrap();

    let commit = module
        .get_function("sx.process.commit.storage")
        .expect("process storage commit declaration");
    builder.position_at_end(context.append_basic_block(commit, "entry"));
    let mut any_changed = context.bool_type().const_zero();
    for storage in &design.process_ir.storages {
        let Some(width) = storage_state_width(design, storage.id) else {
            continue;
        };
        let previous = state_value(
            context,
            module,
            &builder,
            &storage_old_name(storage.id),
            width,
        )
        .expect("declared storage snapshot");
        let mut current = state_value(
            context,
            module,
            &builder,
            &storage_state_name(storage.id),
            width,
        )
        .expect("declared storage state");
        for binding in &storage.bindings {
            if !matches!(
                binding.direction,
                LayoutDirection::Out | LayoutDirection::InOut
            ) {
                continue;
            }
            let (offset, binding_width) =
                storage_binding_slice(design, storage.id, &binding.projection)
                    .expect("validated storage binding");
            let observed = signal_value(
                context,
                module,
                &builder,
                design,
                &[binding.signal],
                ProcessSignalState::Current,
                binding_width,
            )
            .expect("validated observed storage binding");
            current = insert_region(&builder, current, observed, offset, binding_width)
                .expect("validated observed storage region");
        }
        store_state(
            module,
            &builder,
            &storage_state_name(storage.id),
            width,
            current,
        )
        .expect("declared storage state");
        store_state(
            module,
            &builder,
            &storage_old_name(storage.id),
            width,
            current,
        )
        .expect("declared storage snapshot");
        let changed = builder
            .build_int_compare(
                IntPredicate::NE,
                previous,
                current,
                "process.storage.changed",
            )
            .unwrap();
        builder
            .build_store(
                storage_changed_ptr(context, module, &builder, storage_count, storage.id.0),
                builder
                    .build_int_z_extend(changed, byte, "process.storage.changed.byte")
                    .unwrap(),
            )
            .unwrap();
        any_changed = builder
            .build_or(any_changed, changed, "process.storage.any_changed")
            .unwrap();
    }
    builder.build_return(Some(&any_changed)).unwrap();

    let query = module.add_function(
        "sx_process_storage_changed",
        byte.fn_type(&[context.i32_type().into()], false),
        None,
    );
    builder.position_at_end(context.append_basic_block(query, "entry"));
    let storage = query
        .get_first_param()
        .expect("storage change query has an id")
        .into_int_value();
    let in_range = builder
        .build_int_compare(
            IntPredicate::ULT,
            storage,
            context
                .i32_type()
                .const_int(u64::from(storage_count), false),
            "process.storage.changed.in_range",
        )
        .unwrap();
    let safe = builder
        .build_select(
            in_range,
            storage,
            context.i32_type().const_zero(),
            "process.storage.changed.safe_id",
        )
        .unwrap()
        .into_int_value();
    let loaded = builder
        .build_load(
            byte,
            storage_changed_ptr_at(context, module, &builder, storage_count, safe),
            "process.storage.changed.value",
        )
        .unwrap()
        .into_int_value();
    let result = builder
        .build_select(
            in_range,
            loaded,
            byte.const_zero(),
            "process.storage.changed.result",
        )
        .unwrap()
        .into_int_value();
    builder.build_return(Some(&result)).unwrap();
}

/// Whether a block is transactional for the currently implemented direct
/// subset. Unsupported blocks execute no foreign calls and publish no staged
/// writes before returning status 255.
fn block_is_supported(
    design: &Design,
    process: &ProcessCfg,
    block: &siox::ir::ProcessBlock,
    values: &[bool],
) -> bool {
    let value = |id: ProcessValueId| values.get(id.0 as usize).copied().unwrap_or(false);
    let instructions = block
        .instructions
        .iter()
        .all(|instruction| match instruction {
            ProcessInstruction::Declare {
                local, initializer, ..
            } => local_width(design, process.id, *local).is_some() && initializer.is_none_or(value),
            ProcessInstruction::Assign {
                semantics: ProcessAssignment::ImmediateLocal,
                target,
                value: assigned,
                ..
            } => {
                static_place(design, *target).is_some_and(|place| {
                    place_has_semantics(place, process.id, ProcessAssignment::ImmediateLocal)
                }) && value(*assigned)
            }
            ProcessInstruction::Assign {
                semantics: ProcessAssignment::ImmediateStorage,
                target,
                value: assigned,
                ..
            } => {
                static_place(design, *target).is_some_and(|place| {
                    place_has_semantics(place, process.id, ProcessAssignment::ImmediateStorage)
                }) && value(*assigned)
            }
            ProcessInstruction::Assign {
                semantics: ProcessAssignment::StagedSignal,
                target,
                value: assigned,
                ..
            } => {
                (staged_signal_group(design, *target).is_some()
                    || static_place(design, *target).is_some_and(|place| {
                        place_has_semantics(place, process.id, ProcessAssignment::StagedSignal)
                    }))
                    && value(*assigned)
            }
            ProcessInstruction::Assign {
                semantics: ProcessAssignment::PerPlace,
                target,
                value: assigned,
                ..
            } => {
                supported_per_place_assignment(design, process.id, *target, *assigned)
                    && value(*assigned)
            }
            ProcessInstruction::Schedule {
                target,
                value: assigned,
                delay,
                ..
            } => {
                delayed_place(design, *target).is_some()
                    && value(*assigned)
                    && value(*delay)
                    && design
                        .process_ir
                        .values
                        .get(delay.0 as usize)
                        .and_then(|value| value.bit_width)
                        .is_some_and(|width| width <= 64)
            }
            ProcessInstruction::Runtime { .. } => false,
        });
    let terminator = match &block.terminator {
        ProcessTerminator::Return { value: None, .. }
        | ProcessTerminator::Goto(_)
        | ProcessTerminator::Stop { .. }
        | ProcessTerminator::Finish { .. } => true,
        ProcessTerminator::Branch { condition, .. } => value(*condition),
        ProcessTerminator::Suspend {
            operation: siox::ir::ProcessSuspendOp::Await,
            arguments,
            ..
        } => {
            let [delay] = arguments.as_slice() else {
                return false;
            };
            value(*delay)
                && design
                    .process_ir
                    .values
                    .get(delay.0 as usize)
                    .is_some_and(|delay| {
                        delay.bit_width.is_some_and(|width| width <= 64)
                            && matches!(
                                delay.kind,
                                ProcessValueKind::Number(ProcessNumber::Integer(_))
                            )
                    })
        }
        ProcessTerminator::Return { value: Some(_), .. }
        | ProcessTerminator::Match { .. }
        | ProcessTerminator::For { .. } => false,
    };
    instructions && terminator
}

#[allow(clippy::too_many_arguments)]
fn emit_timed_suspend<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    builder: &Builder<'ctx>,
    design: &Design,
    process: ProcessId,
    resume: siox::ir::ProcessBlockId,
    delay: ProcessValueId,
    index_sites: &HashMap<IndexSite, u32>,
    cache: &mut ProcessValueCache<'ctx, '_>,
) -> Option<()> {
    let delay = process_value_at(
        context,
        module,
        builder,
        design,
        delay,
        64,
        false,
        None,
        index_sites,
        cache,
    )?;
    let i32 = context.i32_type();
    let i64 = context.i64_type();
    let function = module
        .get_function("sx_runtime_suspend_time")
        .unwrap_or_else(|| {
            module.add_function(
                "sx_runtime_suspend_time",
                context
                    .void_type()
                    .fn_type(&[i32.into(), i32.into(), i64.into()], false),
                Some(Linkage::External),
            )
        });
    builder
        .build_call(
            function,
            &[
                i32.const_int(u64::from(process.0), false).into(),
                i32.const_int(u64::from(resume.0), false).into(),
                delay.into(),
            ],
            "",
        )
        .ok()?;
    Some(())
}

/// Emit a process entry that resumes at any CFG block by its stable block ID.
///
/// Blocks containing directly supported assignments execute and publish
/// staged writes into the object-owned pending state. Unsupported
/// executable nodes return [`PROCESS_UNSUPPORTED`] before a block performs any
/// calls or writes, making this a safe migration path rather than a second
/// partial semantic engine.
#[allow(clippy::too_many_arguments)]
fn process_entry<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    design: &Design,
    process: &ProcessCfg,
    index_sites: &HashMap<IndexSite, u32>,
    range_sites: &HashMap<siox::diag::Span, u32>,
    checked_values: &[bool],
    schedule_ids: &HashMap<(ProcessId, siox::ir::ProcessBlockId, usize), u32>,
) -> FunctionValue<'ctx> {
    let i8 = context.i8_type();
    let i32 = context.i32_type();
    let function = module.add_function(
        &format!("sx.process.{}", process.id.0),
        i8.fn_type(&[i32.into()], false),
        Some(Linkage::Internal),
    );
    let builder = context.create_builder();
    let dispatch = context.append_basic_block(function, "dispatch");
    let invalid = context.append_basic_block(function, "invalid");
    let blocks = process
        .blocks
        .iter()
        .map(|block| context.append_basic_block(function, &format!("bb{}", block.id.0)))
        .collect::<Vec<_>>();

    builder.position_at_end(dispatch);
    let resume = function
        .get_first_param()
        .expect("process entry has a resume block")
        .into_int_value();
    let cases = process
        .blocks
        .iter()
        .zip(&blocks)
        .map(|(block, llvm)| (i32.const_int(u64::from(block.id.0), false), *llvm))
        .collect::<Vec<_>>();
    builder.build_switch(resume, invalid, &cases).unwrap();

    builder.position_at_end(invalid);
    builder
        .build_return(Some(&i8.const_int(u64::from(PROCESS_UNSUPPORTED), false)))
        .unwrap();

    let supported_values = supported_process_values(design);
    for (block, llvm) in process.blocks.iter().zip(&blocks) {
        builder.position_at_end(*llvm);
        if !block_is_supported(design, process, block, &supported_values) {
            builder
                .build_return(Some(&i8.const_int(u64::from(PROCESS_UNSUPPORTED), false)))
                .unwrap();
            continue;
        }

        let mut cache = ProcessValueCache::new(checked_values);
        let mut failed = false;
        for (instruction_index, instruction) in block.instructions.iter().enumerate() {
            let emitted = match instruction {
                ProcessInstruction::Declare {
                    local, initializer, ..
                } => local_width(design, process.id, *local).and_then(|width| {
                    let metadata = design
                        .process_ir
                        .processes
                        .get(process.id.0 as usize)?
                        .locals
                        .get(local.0 as usize)?;
                    let value = match initializer {
                        Some(initializer) => {
                            if let Some(layout) = metadata.layout.as_ref() {
                                process_value_in_layout(
                                    context,
                                    module,
                                    &builder,
                                    design,
                                    *initializer,
                                    layout,
                                    None,
                                    index_sites,
                                    &mut cache,
                                )?
                            } else {
                                process_value_at(
                                    context,
                                    module,
                                    &builder,
                                    design,
                                    *initializer,
                                    width,
                                    false,
                                    None,
                                    index_sites,
                                    &mut cache,
                                )?
                            }
                        }
                        None => {
                            if let Some(layout) = metadata.layout.as_ref() {
                                layout_default_value(context, &builder, design, layout)?
                            } else {
                                context
                                    .custom_width_int_type(std::num::NonZeroU32::new(width)?)
                                    .ok()?
                                    .const_int(local_default(design, process.id, *local), false)
                            }
                        }
                    };
                    store_state(
                        module,
                        &builder,
                        &local_state_name(process.id, *local),
                        width,
                        value,
                    )
                }),
                ProcessInstruction::Assign {
                    semantics: ProcessAssignment::ImmediateLocal,
                    target,
                    value,
                    span,
                    ..
                } => static_place(design, *target)
                    .filter(|place| {
                        place_has_semantics(*place, process.id, ProcessAssignment::ImmediateLocal)
                    })
                    .and_then(|place| {
                        let value = assignment_value(
                            context,
                            module,
                            &builder,
                            design,
                            *target,
                            *value,
                            place.width,
                            index_sites,
                            &mut cache,
                        )?;
                        write_static_place(
                            context,
                            module,
                            &builder,
                            design,
                            place,
                            value,
                            *span,
                            range_sites,
                        )
                    }),
                ProcessInstruction::Assign {
                    semantics: ProcessAssignment::ImmediateStorage,
                    target,
                    value,
                    span,
                    ..
                } => static_place(design, *target)
                    .filter(|place| {
                        place_has_semantics(*place, process.id, ProcessAssignment::ImmediateStorage)
                    })
                    .and_then(|place| {
                        let value = assignment_value(
                            context,
                            module,
                            &builder,
                            design,
                            *target,
                            *value,
                            place.width,
                            index_sites,
                            &mut cache,
                        )?;
                        write_static_place(
                            context,
                            module,
                            &builder,
                            design,
                            place,
                            value,
                            *span,
                            range_sites,
                        )
                    }),
                ProcessInstruction::Assign {
                    semantics: ProcessAssignment::StagedSignal,
                    target,
                    value,
                    span,
                    ..
                } => (|| {
                    if let Some(signal) = staged_signal_target(design, *target) {
                        let width = design.signal_width(signal)?;
                        let source_width =
                            design.process_ir.values.get(value.0 as usize)?.bit_width?;
                        let ranged = design.signals.get(signal.0 as usize)?.range.is_some();
                        let checked_width = if ranged {
                            width.max(source_width).max(64)
                        } else {
                            width
                        };
                        let value = process_value_at(
                            context,
                            module,
                            &builder,
                            design,
                            *value,
                            checked_width,
                            ranged,
                            None,
                            index_sites,
                            &mut cache,
                        )?;
                        if ranged {
                            latch_range_failure(
                                context,
                                module,
                                &builder,
                                design,
                                signal,
                                value,
                                *span,
                                range_sites,
                            )?;
                        }
                        stage_signal(module, &builder, signal, fit(&builder, value, width)?)
                    } else if let Some(signals) = staged_signal_group(design, *target) {
                        let width = signals.iter().try_fold(0u32, |width, signal| {
                            width.checked_add(design.signal_width(*signal)?)
                        })?;
                        let value = assignment_value(
                            context,
                            module,
                            &builder,
                            design,
                            *target,
                            *value,
                            width,
                            index_sites,
                            &mut cache,
                        )?;
                        stage_signal_group(
                            context,
                            module,
                            &builder,
                            design,
                            signals,
                            value,
                            *span,
                            range_sites,
                        )
                    } else {
                        let place = static_place(design, *target).filter(|place| {
                            place_has_semantics(*place, process.id, ProcessAssignment::StagedSignal)
                        })?;
                        let value = assignment_value(
                            context,
                            module,
                            &builder,
                            design,
                            *target,
                            *value,
                            place.width,
                            index_sites,
                            &mut cache,
                        )?;
                        write_static_place(
                            context,
                            module,
                            &builder,
                            design,
                            place,
                            value,
                            *span,
                            range_sites,
                        )
                    }
                })(),
                ProcessInstruction::Assign {
                    semantics: ProcessAssignment::PerPlace,
                    target,
                    value,
                    span,
                    ..
                } => per_place_targets(design, *target).and_then(|places| {
                    let width = places
                        .iter()
                        .try_fold(0u32, |width, place| width.checked_add(place.width))?;
                    let value = process_value_at(
                        context,
                        module,
                        &builder,
                        design,
                        *value,
                        width,
                        false,
                        None,
                        index_sites,
                        &mut cache,
                    )?;
                    let mut offset = width;
                    for place in places {
                        offset = offset.checked_sub(place.width)?;
                        let part = extract_region(&builder, value, offset, place.width)?;
                        write_static_place(
                            context,
                            module,
                            &builder,
                            design,
                            place,
                            part,
                            *span,
                            range_sites,
                        )?;
                    }
                    (offset == 0).then_some(())
                }),
                ProcessInstruction::Schedule {
                    target,
                    value,
                    delay,
                    ..
                } => schedule_ids
                    .get(&(process.id, block.id, instruction_index))
                    .and_then(|site| {
                        emit_schedule_call(
                            context,
                            module,
                            &builder,
                            design,
                            *site,
                            *target,
                            *value,
                            *delay,
                            index_sites,
                            &mut cache,
                        )
                    }),
                ProcessInstruction::Runtime { .. } => None,
            };
            if emitted.is_none() {
                failed = true;
                break;
            }
            if matches!(
                instruction,
                ProcessInstruction::Declare { .. }
                    | ProcessInstruction::Assign {
                        semantics: ProcessAssignment::ImmediateLocal
                            | ProcessAssignment::ImmediateStorage
                            | ProcessAssignment::PerPlace,
                        ..
                    }
            ) {
                // Immediate writes must invalidate an earlier arena load of
                // the same place. Staged signal writes deliberately do not.
                cache.clear();
            }
        }
        let branch_condition = match &block.terminator {
            ProcessTerminator::Branch { condition, .. } => process_value(
                context,
                module,
                &builder,
                design,
                *condition,
                None,
                index_sites,
                &mut cache,
            )
            .and_then(|condition| as_condition(&builder, condition)),
            _ => None,
        };
        if failed
            || matches!(block.terminator, ProcessTerminator::Branch { .. })
                && branch_condition.is_none()
        {
            builder
                .build_return(Some(&i8.const_int(u64::from(PROCESS_UNSUPPORTED), false)))
                .unwrap();
            continue;
        }

        match &block.terminator {
            ProcessTerminator::Return { value: None, .. } => {
                builder
                    .build_return(Some(&i8.const_int(u64::from(PROCESS_COMPLETED), false)))
                    .unwrap();
            }
            ProcessTerminator::Goto(target) => {
                builder
                    .build_unconditional_branch(blocks[target.0 as usize])
                    .unwrap();
            }
            ProcessTerminator::Stop { .. } => {
                builder
                    .build_return(Some(&i8.const_int(u64::from(PROCESS_STOPPED), false)))
                    .unwrap();
            }
            ProcessTerminator::Finish { .. } => {
                builder
                    .build_return(Some(&i8.const_int(u64::from(PROCESS_FINISHED), false)))
                    .unwrap();
            }
            ProcessTerminator::Branch {
                then_block,
                else_block,
                ..
            } => {
                builder
                    .build_conditional_branch(
                        branch_condition.expect("supported branch condition was emitted"),
                        blocks[then_block.0 as usize],
                        blocks[else_block.0 as usize],
                    )
                    .unwrap();
            }
            ProcessTerminator::Suspend {
                operation: siox::ir::ProcessSuspendOp::Await,
                arguments,
                resume,
                ..
            } => {
                let emitted = arguments.first().copied().and_then(|delay| {
                    emit_timed_suspend(
                        context,
                        module,
                        &builder,
                        design,
                        process.id,
                        *resume,
                        delay,
                        index_sites,
                        &mut cache,
                    )
                });
                builder
                    .build_return(Some(&i8.const_int(
                        u64::from(if emitted.is_some() {
                            PROCESS_SUSPENDED
                        } else {
                            PROCESS_UNSUPPORTED
                        }),
                        false,
                    )))
                    .unwrap();
            }
            ProcessTerminator::Return { value: Some(_), .. }
            | ProcessTerminator::Match { .. }
            | ProcessTerminator::For { .. } => {
                builder
                    .build_return(Some(&i8.const_int(u64::from(PROCESS_UNSUPPORTED), false)))
                    .unwrap();
            }
        }
    }
    function
}

fn scheduled_value_from_words<'ctx>(
    context: &'ctx Context,
    builder: &Builder<'ctx>,
    words: PointerValue<'ctx>,
    width: u32,
) -> Option<IntValue<'ctx>> {
    let i32 = context.i32_type();
    let i64 = context.i64_type();
    let ty = context
        .custom_width_int_type(std::num::NonZeroU32::new(width)?)
        .ok()?;
    let mut value = ty.const_zero();
    for word in 0..super::words_for(width) {
        let source = unsafe {
            builder
                .build_in_bounds_gep(
                    i64,
                    words,
                    &[i32.const_int(u64::from(word), false)],
                    "process.scheduled.word.pointer",
                )
                .ok()?
        };
        let part = builder
            .build_load(i64, source, "process.scheduled.word")
            .ok()?
            .into_int_value();
        let part = fit(builder, part, width)?;
        let offset = word.checked_mul(super::ABI_WORD_BITS)?;
        let part = if offset == 0 {
            part
        } else {
            builder
                .build_left_shift(
                    part,
                    ty.const_int(u64::from(offset), false),
                    "process.scheduled.word.place",
                )
                .ok()?
        };
        value = builder
            .build_or(value, part, "process.scheduled.value")
            .ok()?;
    }
    Some(value)
}

/// Apply one expired delayed-write site. The fixed runtime owns time and
/// copies ABI words; this emitted dispatcher owns the target's concrete LLVM
/// layout and stages the write into the ordinary commit boundary.
fn emit_scheduled_apply<'ctx>(
    context: &'ctx Context,
    module: &Module<'ctx>,
    design: &Design,
    sites: &[ScheduleSite],
    range_sites: &HashMap<siox::diag::Span, u32>,
) {
    let i8 = context.i8_type();
    let i32 = context.i32_type();
    let pointer = context.ptr_type(AddressSpace::default());
    let function = module.add_function(
        "sx_process_apply_scheduled",
        i8.fn_type(&[i32.into(), pointer.into(), i32.into()], false),
        None,
    );
    let builder = context.create_builder();
    let dispatch = context.append_basic_block(function, "dispatch");
    let invalid = context.append_basic_block(function, "invalid");
    let blocks = sites
        .iter()
        .map(|site| context.append_basic_block(function, &format!("site{}", site.id)))
        .collect::<Vec<_>>();
    let applies = sites
        .iter()
        .map(|site| context.append_basic_block(function, &format!("site{}.apply", site.id)))
        .collect::<Vec<_>>();

    builder.position_at_end(dispatch);
    let site_id = function
        .get_nth_param(0)
        .expect("scheduled callback has a site id")
        .into_int_value();
    let words = function
        .get_nth_param(1)
        .expect("scheduled callback has value words")
        .into_pointer_value();
    let count = function
        .get_nth_param(2)
        .expect("scheduled callback has a word count")
        .into_int_value();
    let cases = sites
        .iter()
        .zip(&blocks)
        .map(|(site, block)| (i32.const_int(u64::from(site.id), false), *block))
        .collect::<Vec<_>>();
    builder.build_switch(site_id, invalid, &cases).unwrap();

    builder.position_at_end(invalid);
    builder
        .build_return(Some(&i8.const_int(u64::from(PROCESS_UNSUPPORTED), false)))
        .unwrap();

    for ((site, block), apply) in sites.iter().zip(&blocks).zip(&applies) {
        builder.position_at_end(*block);
        let expected = i32.const_int(u64::from(super::words_for(site.width)), false);
        let valid = builder
            .build_int_compare(
                IntPredicate::EQ,
                count,
                expected,
                "process.scheduled.word_count",
            )
            .unwrap();
        builder
            .build_conditional_branch(valid, *apply, invalid)
            .unwrap();

        builder.position_at_end(*apply);
        let emitted = delayed_place(design, site.target)
            .zip(scheduled_value_from_words(
                context, &builder, words, site.width,
            ))
            .and_then(|(place, value)| {
                write_static_place(
                    context,
                    module,
                    &builder,
                    design,
                    place,
                    value,
                    site.span,
                    range_sites,
                )
            });
        builder
            .build_return(Some(&i8.const_int(
                u64::from(if emitted.is_some() {
                    PROCESS_COMPLETED
                } else {
                    PROCESS_UNSUPPORTED
                }),
                false,
            )))
            .unwrap();
    }
}

/// Emit the opaque function-pointer table consumed by the native scheduler.
fn process_entry_table<'ctx>(context: &'ctx Context, module: &Module<'ctx>, design: &Design) {
    let pointer = context.ptr_type(AddressSpace::default());
    let index_sites = design
        .index_sites()
        .into_iter()
        .enumerate()
        .map(|(index, site)| (site, index as u32 + 1))
        .collect::<HashMap<_, _>>();
    let range_sites = design
        .range_sites()
        .into_iter()
        .enumerate()
        .map(|(index, span)| (span, index as u32 + 1))
        .collect::<HashMap<_, _>>();
    let checked_values = checked_process_values(design);
    let schedule_sites = schedule_sites(design);
    let schedule_ids = schedule_sites
        .iter()
        .map(|site| ((site.process, site.block, site.instruction), site.id))
        .collect::<HashMap<_, _>>();
    emit_scheduled_apply(context, module, design, &schedule_sites, &range_sites);
    let values = design
        .process_ir
        .processes
        .iter()
        .map(|process| {
            process_entry(
                context,
                module,
                design,
                process,
                &index_sites,
                &range_sites,
                &checked_values,
                &schedule_ids,
            )
            .as_global_value()
            .as_pointer_value()
        })
        .collect::<Vec<_>>();
    let fallback = [pointer.const_null()];
    let initializer = pointer.const_array(if values.is_empty() {
        &fallback
    } else {
        &values
    });
    let global = module.add_global(initializer.get_type(), None, "sx_process_entries");
    global.set_initializer(&initializer);
    global.set_constant(true);
}

/// Materialize the runtime-facing test/process descriptor tables.
///
/// All lists use offset + flattened-value tables, avoiding generated symbols
/// whose shape changes per test. Process sensitivity kinds are encoded as
/// `0 = signal` and `1 = persistent storage`; process activation is `0 = once
/// at time zero`, `1 = reactive`. The counts make the sentinel elements of
/// logically empty arrays unobservable.
pub(super) fn emit_metadata<'ctx>(context: &'ctx Context, module: &Module<'ctx>, design: &Design) {
    let process_ir = &design.process_ir;
    emit_state_helpers(context, module, design);
    u32_global(
        context,
        module,
        "sx_process_abi_version",
        PROCESS_ABI_VERSION,
    );
    u32_global(
        context,
        module,
        "sx_test_count",
        process_ir.tests.len() as u32,
    );
    u32_global(
        context,
        module,
        "sx_process_count",
        process_ir.processes.len() as u32,
    );
    test_name_table(context, module, design);
    process_entry_table(context, module, design);

    let test_roots = process_ir
        .tests
        .iter()
        .map(|test| test.root.0)
        .collect::<Vec<_>>();
    let mut test_process_offsets = Vec::with_capacity(process_ir.tests.len() + 1);
    let mut test_process_ids = Vec::new();
    for test in &process_ir.tests {
        test_process_offsets.push(test_process_ids.len() as u32);
        test_process_ids.extend(test.processes.iter().map(|process| process.0));
    }
    test_process_offsets.push(test_process_ids.len() as u32);
    u32_table(context, module, "sx_test_roots", &test_roots);
    u32_table(
        context,
        module,
        "sx_test_process_offsets",
        &test_process_offsets,
    );
    u32_table(context, module, "sx_test_process_ids", &test_process_ids);

    let roots = process_ir
        .processes
        .iter()
        .map(|process| process.root.0)
        .collect::<Vec<_>>();
    let owners = process_ir
        .processes
        .iter()
        .map(|process| process.owner.0)
        .collect::<Vec<_>>();
    let initial_blocks = process_ir
        .processes
        .iter()
        .map(|process| process.entry.0)
        .collect::<Vec<_>>();
    let activations = process_ir
        .processes
        .iter()
        .map(|process| match process.activation {
            ProcessActivation::TimeZero => 0,
            ProcessActivation::Reactive { .. } => 1,
        })
        .collect::<Vec<_>>();
    let mut sensitivity_offsets = Vec::with_capacity(process_ir.processes.len() + 1);
    let mut sensitivity_kinds = Vec::new();
    let mut sensitivity_ids = Vec::new();
    for process in &process_ir.processes {
        sensitivity_offsets.push(sensitivity_ids.len() as u32);
        if let ProcessActivation::Reactive { sensitivity } = &process.activation {
            for item in sensitivity {
                match item {
                    ProcessSensitivity::Signal(signal) => {
                        sensitivity_kinds.push(0);
                        sensitivity_ids.push(signal.0);
                    }
                    ProcessSensitivity::Storage(storage) => {
                        sensitivity_kinds.push(1);
                        sensitivity_ids.push(storage.0);
                    }
                }
            }
        }
    }
    sensitivity_offsets.push(sensitivity_ids.len() as u32);

    u32_table(context, module, "sx_process_roots", &roots);
    u32_table(context, module, "sx_process_owners", &owners);
    u32_table(
        context,
        module,
        "sx_process_initial_blocks",
        &initial_blocks,
    );
    u8_table(context, module, "sx_process_activations", &activations);
    u32_table(
        context,
        module,
        "sx_process_sensitivity_offsets",
        &sensitivity_offsets,
    );
    u8_table(
        context,
        module,
        "sx_process_sensitivity_kinds",
        &sensitivity_kinds,
    );
    u32_table(
        context,
        module,
        "sx_process_sensitivity_ids",
        &sensitivity_ids,
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    use siox::diag::{FileId, Span};
    use siox::elab::InstanceId;
    use siox::ir::{
        ProcessBlock, ProcessBlockId, ProcessCfg, ProcessId, ProcessIr, ProcessSignalState,
        ProcessTerminator, ProcessTest, ProcessValue, ProcessValueId, ProcessValueKind, Signal,
        SignalId,
    };
    use siox::resolve::DefId;

    /// A source-less span for hand-built backend fixtures.
    fn span() -> Span {
        Span::new(FileId(0), 0..0)
    }

    /// The design object exports stable flattened descriptors without any
    /// generated C declaration list.
    #[test]
    fn emits_runtime_discovery_metadata() {
        let process_ir = ProcessIr {
            processes: vec![
                ProcessCfg {
                    id: ProcessId(0),
                    root: InstanceId(7),
                    owner: InstanceId(7),
                    label: Some("stimulus".into()),
                    span: span(),
                    activation: ProcessActivation::TimeZero,
                    entry: ProcessBlockId(0),
                    locals: vec![],
                    blocks: vec![ProcessBlock {
                        id: ProcessBlockId(0),
                        instructions: vec![],
                        terminator: ProcessTerminator::Return {
                            value: None,
                            span: None,
                        },
                    }],
                },
                ProcessCfg {
                    id: ProcessId(1),
                    root: InstanceId(7),
                    owner: InstanceId(8),
                    label: Some("dut.y".into()),
                    span: span(),
                    activation: ProcessActivation::Reactive {
                        sensitivity: vec![ProcessSensitivity::Signal(siox::ir::SignalId(0))],
                    },
                    entry: ProcessBlockId(0),
                    locals: vec![],
                    blocks: vec![ProcessBlock {
                        id: ProcessBlockId(0),
                        instructions: vec![],
                        terminator: ProcessTerminator::Return {
                            value: None,
                            span: None,
                        },
                    }],
                },
            ],
            tests: vec![ProcessTest {
                entity: DefId(11),
                root: InstanceId(7),
                qualified_name: "examples::Smoke".into(),
                span: span(),
                processes: vec![ProcessId(0), ProcessId(1)],
            }],
            storages: vec![],
            values: vec![],
        };
        let design = Design {
            signals: vec![siox::ir::Signal {
                path: "Smoke.dut.input".into(),
                declaration_span: span(),
                width: 1,
                real: false,
                integer: false,
                char: false,
                range: None,
                init: vec![0],
                enum_type: None,
            }],
            process_ir,
            ..Design::default()
        };
        let llvm = crate::llvm::emit_module_ir(&design).unwrap();
        assert!(llvm.contains("@sx_process_abi_version = constant i32 6"));
        assert!(llvm.contains("define i8 @sx_process_commit()"));
        assert!(llvm.contains("define i8 @sx_process_changed(i32"));
        assert!(llvm.contains("define i8 @sx_process_storage_changed(i32"));
        assert!(llvm.contains("define internal void @sx.process.stage.0(i1"));
        assert!(llvm.contains("@sx_test_count = constant i32 1"));
        assert!(llvm.contains("@sx_process_count = constant i32 2"));
        assert!(
            llvm.contains("@sx.test.name.0 = private constant [16 x i8] c\"examples::Smoke\\00\"")
        );
        assert!(llvm.contains("@sx_test_process_offsets = constant [2 x i32] [i32 0, i32 2]"));
        assert!(llvm.contains("@sx_test_process_ids = constant [2 x i32] [i32 0, i32 1]"));
        assert!(llvm.contains(
            "@sx_process_entries = constant [2 x ptr] [ptr @sx.process.0, ptr @sx.process.1]"
        ));
        assert!(llvm.contains("@sx_process_initial_blocks = constant [2 x i32] zeroinitializer"));
        assert!(llvm.contains("@sx_process_activations = constant [2 x i8] c\"\\00\\01\""));
        assert!(llvm.contains(
            "@sx_process_sensitivity_offsets = constant [3 x i32] [i32 0, i32 0, i32 1]"
        ));
        assert!(llvm.contains("@sx_process_sensitivity_ids = constant [1 x i32] zeroinitializer"));
        assert!(llvm.contains("define internal i8 @sx.process.0(i32"));
        assert!(llvm.contains("define internal i8 @sx.process.1(i32"));
    }

    /// Empty logical descriptor tables still have legal storage for the C ABI,
    /// while their exported counts remain zero.
    #[test]
    fn empty_design_uses_unobservable_sentinels() {
        let llvm = crate::llvm::emit_module_ir(&Design::default()).unwrap();
        assert!(llvm.contains("@sx_test_count = constant i32 0"));
        assert!(llvm.contains("@sx_process_count = constant i32 0"));
        assert!(llvm.contains("@sx_test_names = constant [1 x ptr] zeroinitializer"));
        assert!(llvm.contains("@sx_process_entries = constant [1 x ptr] zeroinitializer"));
        assert!(llvm.contains("@sx_process_activations = constant [1 x i8] zeroinitializer"));
    }

    /// Resume dispatch preserves CFG block identity and emits the stable
    /// control-only status values before executable instruction coverage.
    #[test]
    fn process_entries_dispatch_control_only_cfgs() {
        let process_ir = ProcessIr {
            processes: vec![ProcessCfg {
                id: ProcessId(0),
                root: InstanceId(0),
                owner: InstanceId(0),
                label: Some("control".into()),
                span: span(),
                activation: ProcessActivation::TimeZero,
                entry: ProcessBlockId(0),
                locals: vec![],
                blocks: vec![
                    ProcessBlock {
                        id: ProcessBlockId(0),
                        instructions: vec![],
                        terminator: ProcessTerminator::Goto(ProcessBlockId(1)),
                    },
                    ProcessBlock {
                        id: ProcessBlockId(1),
                        instructions: vec![],
                        terminator: ProcessTerminator::Stop { span: span() },
                    },
                    ProcessBlock {
                        id: ProcessBlockId(2),
                        instructions: vec![],
                        terminator: ProcessTerminator::Finish { span: span() },
                    },
                    ProcessBlock {
                        id: ProcessBlockId(3),
                        instructions: vec![],
                        terminator: ProcessTerminator::Return {
                            value: Some(siox::ir::ProcessValueId(0)),
                            span: Some(span()),
                        },
                    },
                ],
            }],
            values: vec![siox::ir::ProcessValue {
                span: span(),
                ty: Some(siox::types::Ty::Integer),
                bit_width: Some(64),
                kind: siox::ir::ProcessValueKind::Number(siox::ir::ProcessNumber::Integer(vec![1])),
            }],
            ..ProcessIr::default()
        };
        let llvm = crate::llvm::emit_module_ir(&Design {
            process_ir,
            ..Design::default()
        })
        .unwrap();
        assert!(llvm.contains("i32 0, label %bb0"), "{llvm}");
        assert!(llvm.contains("i32 3, label %bb3"), "{llvm}");
        let body = |label: &str| {
            llvm.split_once(label)
                .map(|(_, rest)| rest.split_once("\n\n").map_or(rest, |(block, _)| block))
                .expect("emitted process block")
        };
        assert!(body("bb0:").contains("br label %bb1"), "{llvm}");
        assert!(body("bb1:").contains("ret i8 2"), "{llvm}");
        assert!(body("bb2:").contains("ret i8 3"), "{llvm}");
        assert!(body("bb3:").contains("ret i8 -1"), "{llvm}");
    }

    /// Direct branch lowering reconstructs current/old state from as many ABI
    /// words as required, combines it with event state, and branches on a
    /// selected high bit.
    #[test]
    fn process_branch_reads_exact_width_state_and_operations() {
        let process_ir = ProcessIr {
            processes: vec![ProcessCfg {
                id: ProcessId(0),
                root: InstanceId(0),
                owner: InstanceId(0),
                label: Some("wide-branch".into()),
                span: span(),
                activation: ProcessActivation::TimeZero,
                entry: ProcessBlockId(0),
                locals: vec![],
                blocks: vec![
                    ProcessBlock {
                        id: ProcessBlockId(0),
                        instructions: vec![],
                        terminator: ProcessTerminator::Branch {
                            condition: ProcessValueId(6),
                            then_block: ProcessBlockId(1),
                            else_block: ProcessBlockId(2),
                        },
                    },
                    ProcessBlock {
                        id: ProcessBlockId(1),
                        instructions: vec![],
                        terminator: ProcessTerminator::Stop { span: span() },
                    },
                    ProcessBlock {
                        id: ProcessBlockId(2),
                        instructions: vec![],
                        terminator: ProcessTerminator::Finish { span: span() },
                    },
                ],
            }],
            values: vec![
                ProcessValue {
                    span: span(),
                    ty: None,
                    bit_width: Some(65),
                    kind: ProcessValueKind::Signal {
                        signals: vec![SignalId(0)],
                        state: ProcessSignalState::Current,
                    },
                },
                ProcessValue {
                    span: span(),
                    ty: None,
                    bit_width: Some(65),
                    kind: ProcessValueKind::Signal {
                        signals: vec![SignalId(0)],
                        state: ProcessSignalState::Old,
                    },
                },
                ProcessValue {
                    span: span(),
                    ty: None,
                    bit_width: Some(1),
                    kind: ProcessValueKind::Signal {
                        signals: vec![SignalId(0)],
                        state: ProcessSignalState::Event,
                    },
                },
                ProcessValue {
                    span: span(),
                    ty: None,
                    bit_width: Some(1),
                    kind: ProcessValueKind::Binary {
                        operation: ProcessBinaryOp::Ne,
                        left: ProcessValueId(0),
                        right: ProcessValueId(1),
                    },
                },
                ProcessValue {
                    span: span(),
                    ty: None,
                    bit_width: Some(1),
                    kind: ProcessValueKind::BitSlice {
                        base: ProcessValueId(0),
                        high: 64,
                        low: 64,
                    },
                },
                ProcessValue {
                    span: span(),
                    ty: None,
                    bit_width: Some(1),
                    kind: ProcessValueKind::Binary {
                        operation: ProcessBinaryOp::And,
                        left: ProcessValueId(2),
                        right: ProcessValueId(3),
                    },
                },
                ProcessValue {
                    span: span(),
                    ty: None,
                    bit_width: Some(1),
                    kind: ProcessValueKind::Binary {
                        operation: ProcessBinaryOp::And,
                        left: ProcessValueId(4),
                        right: ProcessValueId(5),
                    },
                },
            ],
            ..ProcessIr::default()
        };
        let design = Design {
            signals: vec![Signal {
                path: "Wide.flag".into(),
                declaration_span: span(),
                width: 65,
                real: false,
                integer: false,
                char: false,
                range: None,
                init: vec![0, 0],
                enum_type: None,
            }],
            process_ir,
            ..Design::default()
        };
        let llvm = crate::llvm::emit_module_ir(&design).unwrap();
        assert!(
            llvm.contains("call i64 @sx_read_word(i32 0, i32 0)"),
            "{llvm}"
        );
        assert!(
            llvm.contains("call i64 @sx_read_word(i32 0, i32 1)"),
            "{llvm}"
        );
        assert!(
            llvm.contains("call i64 @sx.process.read.old(i32 0, i32 1)"),
            "{llvm}"
        );
        assert!(
            llvm.contains("call i64 @sx.process.read.event(i32 0, i32 0)"),
            "{llvm}"
        );
        assert!(llvm.contains("lshr i65"), "{llvm}");
        assert!(llvm.contains("icmp ne i65"), "{llvm}");
        assert!(llvm.contains("and i1"), "{llvm}");
        assert!(llvm.contains("br i1"), "{llvm}");
    }

    /// Oversized process-only values fail before asking LLVM to construct an
    /// unsupported integer type, even when no hardware signal has that width.
    #[test]
    fn unsupported_process_value_width_is_an_error_not_a_panic() {
        let process_ir = ProcessIr {
            values: vec![ProcessValue {
                span: span(),
                ty: None,
                bit_width: Some(crate::llvm::emit::LLVM_MAX_INT_BITS + 1),
                kind: ProcessValueKind::Number(siox::ir::ProcessNumber::Integer(vec![0])),
            }],
            ..ProcessIr::default()
        };
        let error = crate::llvm::emit_module_ir(&Design {
            process_ir,
            ..Design::default()
        })
        .unwrap_err();
        assert!(error.contains("process value 0"), "{error}");
        assert!(
            error.contains(&crate::llvm::emit::LLVM_MAX_INT_BITS.to_string()),
            "{error}"
        );
    }
}
